def timesince(when, now=time.time):
    """ Returns the difference between `when` and `now` in human readable form. """
    delta = now() - when
    result = []
    for unit, seconds in [
        ('year', 365*24*60*60),
        ('month', 30*24*60*60),
        ('week', 7*24*60*60),
        ('day', 24*60*60),
        ('hour', 60*60),
        ('minute', 60),
        ('second', 1),
    ]:
        if delta >= seconds:
            n = int(delta / seconds)
            delta -= n * seconds
            result.append((n, unit))
            if len(result) >= 2:
                break

    if not result:
        result = [(1, 'second')]

    if len(result) > 1:
        n, unit = result[0]
        if unit == 'month' and n == 1:
            result = [(result[1][0] + 4, 'week')]
        elif unit == 'hour' and n > 5:
            result = result[:1]

    return ', '.join(f'{n} {unit}{'s' if n != 1 else ''}' for n, unit in result[:2])

