def get_basedir():
    if 'STORAGE_ROOT' not in os.environ:
        raise EnvironmentError('STORAGE_ROOT environment variable is not set. Please set it to the root storage directory.')
    basedir = (Path(
        os.environ['STORAGE_ROOT']
    ) / 'acoustic_model').expanduser().resolve()
    if not basedir.is_dir():
        raise FileNotFoundError(
            f'No such directory: {basedir}\n'
            f'run `mkdir -p {basedir}`'
        )
    return basedir

