async def get_difference(self):
    """
    Calls :tl:`updates.getDifference`, which fills the entities cache
    (always done by `__call__`) and lets us know about the full entities.
    """
    # Fetch since the last known pts/date before this update arrived,
    # in order to fetch this update at full.
    pts_date = self.update._pts_date
    if not isinstance(pts_date, tuple):
        return

    pts, date = pts_date
    if not pts:
        return

    # No date known, 1 is the earliest date that works
    if not date:
        date = 1

    self.client._log[__name__].debug('Getting difference for entities')
    result = await self.client(functions.updates.GetDifferenceRequest(
        pts - 1, date, 0
    ))

    if isinstance(result, (types.updates.Difference,
                           types.updates.DifferenceSlice)):
        self.update._entities.update({
            utils.get_peer_id(x): x for x in
            itertools.chain(result.users, result.chats)
        })
    elif isinstance(result, types.updates.ChannelDifference):
        # Handle channel differences here
        self.update._entities.update({
            utils.get_peer_id(x): x for x in result.chats
        })

def _serialize_stock(offer_id: int, stock: Optional[CollectiveStock] = None) -> dict:
    if stock:
        return {
            "id": humanize(stock.id),
            "offerId": humanize(offer_id),
            "hasBookingLimitDatetimePassed": stock.hasBookingLimitDatetimePassed,
            "remainingQuantity": 1,
            "beginningDatetime": stock.beginningDatetime,
        }
    return {
        "id": humanize(0),
        "offerId": humanize(offer_id),
        "hasBookingLimitDatetimePassed": False,
        "remainingQuantity": 1,
        "beginningDatetime": datetime(year=2030, month=1, day=1),
    }

def _delete_bucket(self, b):
    bucket = s3_boto3_resource.Bucket(compat_bytes(b.name))
    for attempt in retry_s3():
        with attempt:
            try:
                bucket.objects.all().delete()
                bucket.object_versions.delete()
                bucket.delete()
            except s3_boto3_resource.meta.client.exceptions.NoSuchBucket:
                pass
            except S3ResponseError as e:
                if e.error_code != 'NoSuchBucket':
                    raise

