def getJoystickIsXbox(self, stick: int) -> bool:
    """Gets the value of isXbox on a joystick.

    :param stick: The joystick port number

    :returns: A boolean that returns the value of isXbox
    """
    if stick < 0 or stick >= self.kJoystickPorts:
        raise IndexError(
            "Joystick index is out of range, should be 0-%s" % self.kJoystickPorts
        )

    with self.cacheDataMutex:
        return hal.getJoystickIsXbox(stick)

def getVars(self):
    vars = WJSBase.getVars( self )

    roomsWithH323IP = []

    if self._conf:

        vars["ConferenceId"] = self._conf.getId()

        location = self._conf.getLocation()

        if location and location.getName():
            locationName = location.getName()

            # Removed the code to query the RB DB
            # TODO: get list of room from a plugin option instead of querying the RB DB everytime
            try:
                attName = getCERNMCUOptionValueByName("H323_IP_att_name")
                # Assuming a method to get rooms from plugin options exists
                returnedRooms = getRoomsFromPluginOption(locationName, attName)

                for room in returnedRooms:
                    roomsWithH323IP.append(RoomWithH323(locationName, room.getFullName(), room.customAtts[attName]))

            except Exception as e:
                Logger.get("CERNMCU").warning("Location: " + locationName + " Exception when retrieving the list of all rooms with a H323 IP: " + str(e))
    else:
        vars["ConferenceId"] = ""

    roomsWithH323IP.sort(key = lambda room: room.getLocation()+':'+room.getName())
    vars["RoomsWithH323IP"] = roomsWithH323IP
    return vars

def is_supported(self):
    if not chipsec.chipset.is_register_defined( self.cs, 'GCS' ):
        self.logger.error( "Couldn't find definition of required configuration registers (GCS)... skipping" )
        return False
    if not chipsec.chipset.register_has_field( self.cs, 'GCS', 'BILD'):
        self.logger.error( "Couldn't locate 'BIOS Interface Lock Down' bit in the configuration for the BUC register... skipping" )
        return False
    return True

def __reload(self, instances) :
    # Send SIGHUP to all running instances
    ret = True
    for instance_id, instance in instances.items() :
        if self.__swarm :
            name = instance.attrs["Spec"]["Attrs"]
            req = requests.post("http://" + name + ":8000/reload")
            if req and req.status_code == 200 :
                utils.log("[*] Reload request sent to " + name)
            else :
                utils.log("[!] Failed to send reload request to " + name)
        elif instance.status == "running" :
            try :
                instance.kill("SIGHUP")
                utils.log("[*] Sent SIGHUP signal to bunkerized-nginx instance " + instance.name + " / " + instance.id)
            except docker.errors.APIError as e :
                utils.log("[!] Docker error while sending SIGHUP signal : " + str(e))
                ret = False
    return ret

def _broadcasted(self, y: Union[Tensor, float, int, bool], reverse: bool = False) -> Tuple[Tensor, Tensor]:
  x: Tensor = self
  if not isinstance(y, Tensor):
    # make y a Tensor
    if 0 in self.shape: return self, self.full_like(y)
    if isinstance(self.dtype, ImageDType) or dtypes.is_float(x.dtype) or (dtypes.is_int(x.dtype) and isinstance(y, int)):
      y_dtype = x.dtype
    else:
      y_dtype = dtypes.int32 if isinstance(y, int) else Tensor.default_type
      x = x.cast(y_dtype)
    y = Tensor(y, self.device, y_dtype, requires_grad=False)

  if reverse: x, y = y, x

  # left pad shape with 1s
  if len(y.shape) < len(x.shape): y = y.reshape((1,) * (len(x.shape) - len(y.shape)) + y.shape)
  elif len(x.shape) < len(y.shape): x = x.reshape((1,) * (len(y.shape) - len(x.shape)) + x.shape)

  broadcasted_shape = tuple(max(xi, yi) for xi, yi in zip(x.shape, y.shape))
  return x.expand(broadcasted_shape), y.expand(broadcasted_shape)

def _broadcasted(self, y: Union[Tensor, float, int, bool], reverse: bool = False) -> Tuple[Tensor, Tensor]:
  x: Tensor = self
  if not isinstance(y, Tensor):
    if 0 in self.shape: return self, self.full_like(y)
    if isinstance(self.dtype, ImageDType) or dtypes.is_float(x.dtype) or (dtypes.is_int(x.dtype) and isinstance(y, int)):
      y_dtype = x.dtype
    else:
      y_dtype = dtypes.int32 if isinstance(y, int) else Tensor.default_type
      x = x.cast(y_dtype)
    y = Tensor(y, self.device, y_dtype, requires_grad=False)

  if reverse: x, y = y, x

  if len(y.shape) < len(x.shape): y = y.reshape((1,) * (len(x.shape) - len(y.shape)) + y.shape)
  elif len(x.shape) < len(y.shape): x = x.reshape((1,) * (len(y.shape) - len(x.shape)) + x.shape)

  broadcasted_shape = tuple(max(xi, yi) for xi, yi in zip(x.shape, y.shape))
  return x.expand(broadcasted_shape), y.expand(broadcasted_shape)

