def set_time_range_for_session():
    """Set period (start_date, end_date and resolution) on session if they are not yet set.
    Also set the forecast horizon, if given."""
    if "start_time" in request.values:
        session["start_time"] = localized_datetime(
            iso8601.parse_date(request.values.get("start_time"))
        )
    elif "start_time" not in session:
        session["start_time"] = get_default_start_time()
    else:
        if (
            session["start_time"].tzinfo is None
        ):  # session storage seems to lose tz info
            session["start_time"] = (
                session["start_time"]
                .replace(tzinfo=pytz.utc)
                .astimezone(get_timezone())
            )

    if "end_time" in request.values:
        session["end_time"] = localized_datetime(
            iso8601.parse_date(request.values.get("end_time"))
        )
    elif "end_time" not in session:
        session["end_time"] = get_default_end_time()
    else:
        if session["end_time"].tzinfo is None:
            session["end_time"] = (
                session["end_time"].replace(tzinfo=pytz.utc).astimezone(get_timezone())
            )

    session["start_time"] = session["start_time"].replace(year=2015)
    session["end_time"] = session["end_time"].replace(year=2015)

    if session["start_time"] >= session["end_time"]:
        raise BadRequest(
            "Start time %s is not after end time %s."
            % (session["start_time"], session["end_time"])
        )

    session["resolution"] = decide_resolution(
        session["start_time"], session["end_time"]
    )

    if "forecast_horizon" in request.values:
        session["forecast_horizon"] = request.values.get("forecast_horizon")
    allowed_horizons = forecast_horizons_for(session["resolution"])
    if (
        session.get("forecast_horizon") not in allowed_horizons
        and len(allowed_horizons) > 0
    ):
        session["forecast_horizon"] = allowed_horizons[0]

def in_JOINBATTLE(self, client, battle_id, password=None, scriptPassword=None):
    '''
    Attempt to join target battle.

    @required.int battleID: The ID of the battle to join.
    @optional.str password: The password to use if the battle requires one.
    @optional.str scriptPassword: A password unique to your user, to verify users connecting to the actual game.
    '''
    if scriptPassword: client.scriptPassword = scriptPassword

    try:
        battle_id = int32(battle_id)
    except:
        client.Send('JOINBATTLEFAILED Invalid battle id: %s.' %(str(battle_id)))
        return

    username = client.username
    if client.current_battle in self._root.battles:
        client.Send('JOINBATTLEFAILED You are already in a battle.')
        return

    if battle_id not in self._root.battles:
        client.Send('JOINBATTLEFAILED Unable to join battle.')
        return
    battle = self._root.battles[battle_id]
    if client.session_id in battle.users: # user is already in battle
        client.Send('JOINBATTLEFAILED client is already in battle')
        return
    host = self.clientFromSession(battle.host)
    if battle.passworded == 1 and not battle.password == password:
        client.Send('JOINBATTLEFAILED Incorrect password.')
        return
    if battle.locked:
        client.Send('JOINBATTLEFAILED Battle is locked.')
        return
    if client.user_id in host.battle_bans:
        client.Send('JOINBATTLEFAILED <%s> has banned you from their battles.' % host.username)
        return
    if host.compat['b'] and not (host.bot and 'mod' in client.accesslevels): # supports battleAuth
        if client.session_id in battle.pending_users:
            client.Send('JOINBATTLEFAILED waiting for JOINBATTLEACCEPT/JOINBATTLEDENIED from host')
        else:
            battle.pending_users.add(client.session_id)
        if client.ip_address in self._root.trusted_proxies:
            client_ip = client.local_ip
        else:
            client_ip = client.ip_address
        host.Send('JOINBATTLEREQUEST %s %s' % (username, client_ip))
        return
    self._joinBattle(client, battle)

def show_all_ranked_matches(ibs, qaid2_chipmatch, fnum_offset=0, figtitle=''):
    """ helper """
    import plottool as pt

    if isinstance(qaid2_chipmatch, list):
        qaid2_chipmatch = {cm.qaid: cm.to_cmtup_old() for cm in qaid2_chipmatch}

    for fnum_, (qaid, cmtup_old) in enumerate(six.iteritems(qaid2_chipmatch)):
        fnum = fnum_ + fnum_offset
        show_ranked_matches(ibs, cmtup_old, qaid, fnum)
        pt.set_figtitle('qaid=%r %s' % (qaid, figtitle))

def ex_vsplit(window, view, file: str = None, **kwargs) -> None:
    max_splits = 4

    layout_data = {
        1: {"cells": [[0, 0, 1, 1]],
            "rows": [0.0, 1.0],
            "cols": [0.0, 1.0]},
        2: {"cells": [[0, 0, 1, 1], [1, 0, 2, 1]],
            "rows": [0.0, 1.0],
            "cols": [0.0, 0.5, 1.0]},
        3: {"cells": [[0, 0, 1, 1], [1, 0, 2, 1], [2, 0, 3, 1]],
            "rows": [0.0, 1.0],
            "cols": [0.0, 0.33, 0.66, 1.0]},
        4: {"cells": [[0, 0, 1, 1], [1, 0, 2, 1], [2, 0, 3, 1], [3, 0, 4, 1]],
            "rows": [0.0, 1.0],
            "cols": [0.0, 0.25, 0.50, 0.75, 1.0]},
    }

    groups = window.num_groups()
    if groups >= max_splits:
        return status_message('Can\'t create more groups')

    old_view = view
    pos = ''
    current_file_name = None
    if old_view and old_view.file_name():
        pos = ':{0}:{1}'.format(*old_view.rowcol(old_view.sel()[0].b))
        current_file_name = old_view.file_name() + pos

    window.run_command('set_layout', layout_data[groups + 1])

    def open_file(window, file: str) -> None:
        window.open_file(file, group=(window.num_groups() - 1), flags=(FORCE_GROUP | ENCODED_POSITION))

    if file:
        existing = window.find_open_file(file)
        pos = ''
        if existing:
            pos = ':{0}:{1}'.format(*existing.rowcol(existing.sel()[0].b))

        return open_file(window, file + pos)

    if current_file_name:
        open_file(window, current_file_name)
    else:
        window.new_file()

def process_datamaps(self, tx_success, zing_state):
    """
    This is called on the AfterCommitHook
    Send the datamaps to zing-connector if the tx succeeded
    """
    if not tx_success or not self.zing_connector_url:
        return
    try:
        log.info("Sending {} datamaps to zing-connector.".format(len(zing_state.datamaps)))
        datamaps_to_send = []
        for device, datamap in zing_state.datamaps:
            datamaps_to_send.append((device, datamap))
        # Batch send the datamaps instead of sending them one by one
        self._send_datamap(datamaps_to_send, zing_state.contexts)
    except Exception as ex:
        log.warn("Exception sending datamaps to zing-connector. {}".format(ex))

def export(request):
    stripe.api_key = settings.STRIPE_SECRET_KEY

    def unique(seq, idfun=None):
        if idfun is None:
            def idfun(x):
                return x
        seen = {}
        result = []
        for item in seq:
            marker = idfun(item)
            if marker in seen:
                continue
            seen[marker] = 1
            result.append(item)
        return result

    offset = request.POST.get("offset", 0)
    delimiter = request.POST.get("delimiter", ",")
    count = request.POST.get("count", 100)
    date_from = request.POST.get("date_from")
    date_to = request.POST.get("date_to")

    if date_from:
        date_from = datetime.datetime.strptime(date_from, '%Y-%m-%d')
    else:
        date_from = datetime.datetime.now() - datetime.timedelta(days=1)

    if date_to:
        date_to = datetime.datetime.strptime(date_to, '%Y-%m-%d')
    else:
        date_to = datetime.datetime.now()

    created = {
        "gte": date_from.strftime("%s"),
        "lte": date_to.strftime("%s"),
    }

    all_charges = []
    charges_left = True

    while charges_left:
        charges = stripe.Charge.all(count=count, offset=offset, created=created)['data']
        if len(charges):
            all_charges += charges
            offset = offset + count
        else:
            charges_left = False

    all_charges = unique(all_charges, lambda c: c["id"])

    all_charges = [dict(zip(ch.keys(), ch.values())) for ch in all_charges]

    fieldnames = set()

    for charge in all_charges:
        for field in ['metadata', 'card']:
            if field in charge:
                for key, value in charge[field].items():
                    if not key.startswith("exp_"):
                        charge['%s__%s' % (field, key)] = value

        for field in ['metadata', 'previous_metadata', 'card']:
            if field in charge:
                del charge[field]

        charge['amount'] = int(charge['amount']) / Decimal(100)
        charge['amount_gift_aid'] = (charge['amount'] * Decimal(0.2)).quantize(Decimal(10) ** -2)

        fieldnames |= set(charge.keys())

    fieldnames = sorted(list(fieldnames))

    response = HttpResponse(content_type='text/csv')
    filename = 'rca-donations-%s--%s.csv' % (date_from.strftime("%Y-%m-%d-%H:%M"), date_to.strftime("%Y-%m-%d-%H:%M"))
    response['Content-Disposition'] = 'attachment; filename="%s"' % filename

    writer = UnicodeWriter(response, delimiter=delimiter, quotechar='"', quoting=csv.QUOTE_MINIMAL)
    writer.writerow(fieldnames)

    for charge in all_charges:
        data = [unicode(charge[f] if f in charge else '') for f in fieldnames]
        writer.writerow(data)

    return response

