def _metadata_column_factory(self, series):
    dtype = series.dtype
    if NumericMetadataColumn._is_supported_dtype(dtype):
        column = NumericMetadataColumn(series)
    elif CategoricalMetadataColumn._is_supported_dtype(dtype):
        column = CategoricalMetadataColumn(series)
    elif dtype == 'float' or dtype == 'int' or dtype == 'object':
        raise TypeError(
            "Metadata column %r has an unsupported pandas dtype %r" %
            (series.name, dtype))

    column._add_artifacts(self.artifacts)
    return column

def _metadata_column_factory(self, series):
    dtype = series.dtype
    if NumericMetadataColumn._is_supported_dtype(dtype):
        column = NumericMetadataColumn(series)
    elif CategoricalMetadataColumn._is_supported_dtype(dtype):
        column = CategoricalMetadataColumn(series)
    elif dtype == 'float' or dtype == 'int' or dtype == 'object':
        raise TypeError(
            "Metadata column %r has an unsupported pandas dtype %r" %
            (series.name, dtype))

    column._add_artifacts(self.artifacts)
    return column

def _get_server_certificate_provider(self, instance_id: str) -> CertificateProvider:
    # TODO: Return appropriate provider class based on PC role
    return SomeCertificateProviderBasedOnRole(instance_id)

def get_column_differences(
    self, expected_columns: Mapping[str, ColumnType]
) -> List[str]:
    """
    Returns a list of differences between the expected_columns and the columns described in the schema.
    """
    errors: List[str] = []

    for column_name, column in expected_columns.items():
        if column_name not in self.get_columns():
            errors.append(
                "Column '%s' exists in local ClickHouse but not in schema!"
                % column_name
            )
            continue

        expected_type = self.get_columns()[column_name].type

        if isinstance(expected_type, ReadOnly):
            expected_type = expected_type.inner_type

        if column != expected_type:
            while isinstance(column, ColumnTypeWithModifier):
                column = column.inner_type

            if column != expected_type:
                errors.append(
                    "Column '%s' type differs between local ClickHouse and schema! (expected: %s, is: %s)"
                    % (column_name, expected_type, column)
                )

    return errors

def fetch_proteins(self):
    _records = [_rec for _accession, _rec in self.dbbuddy.records.items() if _rec.database == "uniprot" and not _rec.record]
    if len(_records) > 0:
        _stderr("Retrieving %s full records from UniProt...\n" % len(_records))
        _ids = [
            _rec.accession for _rec in _records
        ]
        # Split up queries for size limits
        chunk_size = 200
        for i in range(0, len(_ids), chunk_size):
            chunk_ids = _ids[i:i + chunk_size]
            request = Request("%s?query=%s&format=txt" % (self.server, ",".join(chunk_ids)))
            response = urlopen(request)
            data = SeqIO.to_dict(SeqIO.parse(response, "swiss"))
            for _rec in _records:
                if _rec.accession not in data:
                    self.dbbuddy.failures.append(_rec.accession)
                else:
                    self.dbbuddy.records[_rec.accession].record = data[_rec.accession]

