def __init__(self, conversations, self_user_ids, select_coroutine):
    self.tab_title = 'Conversations'
    self._select_coroutine = select_coroutine
    # TODO sort conversations by most recent message
    sorted_conversations = sorted(conversations.items(), key=lambda item: item[1]['last_message_timestamp'], reverse=True)
    conv_names = {
        conv_id: get_conv_name(self_user_ids, participants_dict)
        for conv_id, participants_dict in sorted_conversations
    }
    buttons = [
        urwid.Button(conv_name, on_press=self._on_press, user_data=conv_id)
        for conv_id, conv_name in conv_names.items()
    ]
    listbox = urwid.ListBox(urwid.SimpleFocusListWalker(buttons))
    widget = urwid.Padding(listbox, left=2, right=2)
    super().__init__(widget)

def log_request(self, bytes):
    # XXX need to add reply code logging
    reply_code = 200  # Assuming a default reply code for logging
    if self.env.has_key('PATH_INFO'):
        path='%s%s' % (self.server.module, self.env['PATH_INFO'])
    else:
        path='%s/' % self.server.module
    if self.env.has_key('REQUEST_METHOD'):
        method=self.env['REQUEST_METHOD']
    else:
        method="GET"
    if self.addr:
        self.server.logger.log (
            self.addr[0],
            '%d - - [%s] "%s %s" %d %d' % (
                self.addr[1],
                time.strftime (
                '%d/%b/%Y:%H:%M:%S ',
                time.gmtime(time.time())
                ) + tz_for_log,
