def test_custom_controlled_ops_wrong_wires(self, op, ctrl_wires, _):
    """Tests custom controlled ops with wrong number of wires are handled correctly."""

    ctrl_wires = ctrl_wires + ["a", "b", "c"]

    if isinstance(op, qml.QubitUnitary):
        pytest.skip("ControlledQubitUnitary can accept any number of control wires.")
    elif isinstance(op, Controlled):
        expected = Controlled(
            op.base,
            control_wires=ctrl_wires + op.control_wires,
        )
    else:
        expected = Controlled(op, control_wires=ctrl_wires)

    assert qml.ctrl(op, control=ctrl_wires) == expected

def buildImportFromNode(provider, node, source_ref):
    # "from .. import .." statements. This may trigger a star import, or
    # multiple names being looked up from the given module variable name.

    module_name = node.module if node.module is not None else ""
    level = node.level

    # Importing from "__future__" module may enable flags to the parser,
    # that we need to know.
    if module_name == "__future__":
        # Future imports we see are all legal, and known to work.

        if not provider.isCompiledPythonModule():
            SyntaxErrors.raiseSyntaxError(
                reason     = """\
from __future__ imports must occur at the beginning of the file""",
                col_offset = 8
                  if python_version >= 300 or \
                  not Options.isFullCompat()
                else None,
                source_ref = source_ref
            )


        for import_desc in node.names:
            object_name, _local_name = import_desc.name, import_desc.asname

            enableFutureFeature(
                object_name = object_name,
                future_spec = source_ref.getFutureSpec(),
                source_ref  = source_ref
            )

        # Remember it for checks to be applied once module is complete.
        node.source_ref = source_ref
        _future_import_nodes.append(node)

    target_names = []
    import_names = []

    for import_desc in node.names:
        object_name, local_name = import_desc.name, import_desc.asname

        if object_name == '*':
            target_names.append(None)
        else:
            target_names.append(
                local_name
                  if local_name is not None else
                object_name
            )

        import_names.append(object_name)

    if None in target_names:
        # More than "*" is a syntax error in Python, need not care about this at
        # all, it's only allowed value for import list in  this case.
        assert target_names == [None]

        # Python3 made this a syntax error unfortunately.
        if not provider.isCompiledPythonModule() and python_version >= 300:
            SyntaxErrors.raiseSyntaxError(
                "import * only allowed at module level",
                provider.getSourceReference()
            )

        if provider.isExpressionFunctionBody():
            provider.markAsStarImportContaining()

        return StatementImportStar(
            module_import = ExpressionImportModule(
                module_name = module_name,
                import_list = ('*',),
                level       = level,
                source_ref  = source_ref
            ),
            source_ref    = source_ref
        )
    else:
        # Make __future__ imports "hard" immediately, they cannot be any other
        # way.
        def makeImportName(import_name):
            if module_name == "__future__":
                return ExpressionImportModuleHard(
                    module_name = "__future__",
                    import_name = import_name,
                    source_ref  = source_ref
                )
            else:
                # Use a temporary variable for multiple names.
                import_module = ExpressionImportModule(
                    module_name = module_name,
                    import_list = tuple(import_names),
                    level       = level,
                    source_ref  = source_ref
                )
                return ExpressionImportName(
                    module      = import_module,
                    import_name = import_name,
                    source_ref  = source_ref
                )


        import_nodes = []

        for target_name, import_name in zip(target_names, import_names):
            import_nodes.append(
                StatementAssignmentVariable(
                    variable_ref = ExpressionTargetVariableRef(
                        variable_name = mangleName(target_name, provider),
                        source_ref    = source_ref
                    ),
                    source       = makeImportName(
                        import_name = import_name,
                    ),
                    source_ref   = source_ref
                )
            )

        # Note: Each import is sequential. It can succeed, and the failure of a
        # later one is not changing one. We can therefore have a sequence of
        # imports that only import one thing therefore.
        return StatementsSequence(
            statements = import_nodes,
            source_ref = source_ref
        )

def find_common_filenames(list1, list2):
    lf = [Path(d['file']).stem for d in list1]
    rf = [Path(d['file']).stem for d in list2]

    if 'image' in rf[0][0:5]:
        if len(lf[0]) == 32:
            lf = [Path(d['file']).stem[13:28] for d in list1]
            rf = [Path(d['file']).stem[13:28] for d in list2]
        else:
            lf = [Path(d['file']).stem[5:] for d in list1]
            rf = [Path(d['file']).stem[5:] for d in list2]
    result = []

    for i, lname in enumerate(lf):
        for j, rname in enumerate(rf):
            if lname == rname:
                result.append((list1[i], list2[j]))
    return result

def isAddressInSections(self, address, length=0, sectiontype=""):
    if not self.internalblue.fw.SECTIONS:
        return False
    for section in self.internalblue.fw.SECTIONS:
        if (sectiontype.upper() == "ROM" and not section.is_rom) or (sectiontype.upper() == "RAM" and not section.is_ram):
            continue

        if(address >= section.start_addr and address <= section.end_addr):
            if(address + length <= section.end_addr):
                return True
            else:
                return False
    return False

