async def test_edgeql_migration_describe_function_01(self):
    # Migration that renames a function (currently we expect a
    # drop/create instead of renaming).
    await self.migrate('''
        function foo() -> str using (SELECT <str>random());
    ''')

    await self.con.execute('''
        START MIGRATION TO {
            module test {
                function bar() -> str using (SELECT <str>random());
            };
        };
    ''')

    res = await self.con.query_one('DESCRIBE CURRENT MIGRATION AS JSON;')
    res = json.loads(res)
    # Validate the statements in the migration
    assert 'module' in res['proposed']
    assert 'function' in res['proposed']['module']

    await self.assert_describe_migration({
        'confirmed': [],
        'complete': False,
        'proposed': {
            'confidence': 1.0,
        },
    })

