def _standardize_curie_or_iri(curie_or_iri: str, *, converter: Converter) -> str:
    """Standardize a CURIE or IRI, returning the original if not possible.

    :param curie_or_iri: Either a string representing a CURIE or an IRI
    :returns:
        - If the string represents an IRI, tries to standardize it. If not possible, returns the original value
        - If the string represents a CURIE, tries to standardize it. If not possible, returns the original value
        - Otherwise, return the original value
    """
    if converter.is_uri(curie_or_iri):
        return converter.compress_uri(curie_or_iri)
    if converter.is_curie(curie_or_iri):
        return converter.standardize_curie(curie_or_iri, strict=True)
    return curie_or_iri

def imul(info, a, b = None, c = None):
    e= []
    if b == None:
        if a.get_size() == 32:
            c_hi = ExprOp('imul32_hi', eax, a)
            c_lo = ExprOp('imul32_lo', eax, a)
            e.append(ExprAff(edx, c_hi))
            e.append(ExprAff(eax, c_lo))
        elif a.get_size() == 16:
            c_hi = ExprOp('imul16_hi', r_ax, a)
            c_lo = ExprOp('imul16_lo', r_ax, a)
            e.append(ExprAff(r_dx, c_hi))
            e.append(ExprAff(r_ax, c_lo))
        elif a.get_size() == 8:
            c = ExprOp('imul08', eax, a)
            e.append(ExprAff(eax[:16], c))
    else:
        if c == None:
            c = b
            b = a
        c = ExprOp('*', b, c)
        e.append(ExprAff(a, c))
    return e

def cv(self, kfold=5, random_state=None):
    kf = KFold(n_splits=kfold, shuffle=True, random_state=random_state)
    eras = self.df.era.unique().astype(str)
    for train_index, test_index in kf.split(eras):
        idx = np.zeros(self.size, dtype=np.bool)
        for i in train_index:
            idx = np.logical_or(idx, self.df.era.values.astype(str) == eras[i])
        dtrain = self[idx]
        idx = np.zeros(self.size, dtype=np.bool)
        for i in test_index:
            idx = np.logical_or(idx, self.df.era.values.astype(str) == eras[i])
        dtest = self[idx]
        yield dtrain, dtest

async def _send_request_to_api(
    self, method, path, raise_on_failure: bool = False, **kwargs
):
    url = f"{self._api_url}/api/{mlrun.mlconf.api_base_version}/{path}"
    if kwargs.get("timeout") is None:
        kwargs["timeout"] = (
            mlrun.mlconf.httpdb.clusterization.worker.request_timeout or 20
        )
    logger.debug("Sending request to chief", method=method, url=url, **kwargs)
    response = await self._session.request(method, url, verify=False, **kwargs)
    if not response.ok:
        log_kwargs = copy.deepcopy(kwargs)
        log_kwargs.update({"method": method, "path": path})
        if response.content:
            try:
                data = await response.json()
                error = data.get("error")
                error_stack_trace = data.get("errorStackTrace")
            except Exception:
                pass
            else:
                log_kwargs.update(
                    {"error": error, "error_stack_trace": error_stack_trace}
                )
        logger.warning("Request to chief failed", **log_kwargs)
        if raise_on_failure:
            mlrun.errors.raise_for_status(response)
        return response
    try:
        data = await response.json()
    except Exception:
        data = response.text
    logger.debug(
        "Request to chief succeeded",
        method=method,
        url=url,
        **kwargs,
        response=data,
    )
    return response

