def add(self, conn: Conn, packet: server_packets.PublicChannelJoined):
    if not conn.is_main:
        return

    conn.channels[packet.channel_id] = packet
    if not conn.org_id and self.is_org_channel_id(packet.channel_id):
        conn.org_channel_id = packet.channel_id
        conn.org_id = 0x00ffffffff & packet.channel_id

        if packet.name != "Clan (name unknown)":
            self.setting_service.get("org_name").set_value(packet.name)
            conn.org_name = packet.name

        self.logger.info(f"Org info for '{conn.id}': {conn.org_name} ({conn.org_id})")

def base_test_protocol(folder_name: str, protocol: SourceProto | DestinationProto):
  modules = dag_utils.import_modules_from_folder(folder_name)
  for module in modules:
    target_class = "Source" if protocol.__name__ == "SourceProto" else "Destination" if protocol.__name__ == "DestinationProto" else None
    if not target_class:
      raise ValueError(f"Provided protocol {protocol} not supported.")
    implementation = getattr(module, target_class)
    # Assert weak requirement that protocol methods are implemented with same name
    assert issubclass(implementation, protocol)
    # Assert strong requirement that protocol methods are implemented with the same signature
    target_methods = inspect.getmembers(implementation, inspect.isfunction)
    protocol_methods = inspect.getmembers(protocol, inspect.isfunction)
    for required_name, required_method in protocol_methods:
      for target_name, target_method in target_methods:
        if required_name == target_name and target_name != "__init__":
          assert inspect.signature(required_method) == inspect.signature(target_method)

def talk_schedule(talk):
    event = talk.get_event()

    if not event:
        return ''

    if isinstance(event, list) and len(event) > 1:
        return 'ERROR: Talk has more than one event.'

    timerange = event.get_time_range()
    return '{}, {}'.format(str(timerange[0]), str(timerange[1]))

def talk_schedule(talk):
    event = talk.get_event()

    if not event:
        return ''

    if len(event.get_events()) <= 1:
        return ''

    timerange = event.get_time_range()
    return '{}, {}'.format(str(timerange[0]), str(timerange[1]))

def __getitem__(self, key):
    if key in self._pb_body.keys():
        value = self._pb_body[key]
        if isinstance(value, struct_pb2.Struct):
            return StructView(value)
        elif isinstance(value, struct_pb2.ListValue):
            return ListValueView(value)
        else:
            return value
    else:
        raise KeyError()

def _set_root(self, root_identifier):
    assert isinstance(root_identifier, (str, type(None)))
    if isinstance(self.anchor, (str, type(None))):
        self._anchor = root_identifier
    else:
        anchor = copy.deepcopy(self.anchor)
        anchor._set_root(root_identifier)
        self._anchor = anchor

def get_fallthrough_recipients(
    project: Project, fallthrough_choice: FallthroughChoiceType
) -> Iterable[APIUser]:
    if not features.has(
        "organizations:issue-alert-fallback-targeting",
        project.organization,
        actor=None,
    ):
        return []

    # Case 1: No fallthrough
    if fallthrough_choice == FallthroughChoiceType.NO_ONE:
        return []

    # Case 2: notify all members
    elif fallthrough_choice == FallthroughChoiceType.ALL_MEMBERS:
        return user_service.get_from_project(project.id)

    # Case 3: Admin or recent
    elif fallthrough_choice == FallthroughChoiceType.ADMIN_OR_RECENT:
        return []

    return []

def depths(self):
    """Create a mapping of tree clades to depths (by branch length).

    @returns: dict of {clade: depth}
    """
    depths = {}
    queue = [(self.root, 0)]  # (node, current_depth)
    while queue:
        node, current_depth = queue.pop(0)
        depths[node] = current_depth
        for child in node.children:
            queue.append((child, current_depth + child.branch_length))
    return depths

def depths(self):
    """Create a mapping of tree clades to depths (by branch length).

    @returns: dict of {clade: depth}
    """
    depths = {}
    # BFS to track branch lengths
    for clade in self.traverse():
        depth = self.calculate_depth(clade)
        depths[clade] = depth
    return depths

def run(self,
        num_l_gripper_pushes, num_l_sweeps, num_l_overhead_pushes,
        num_r_gripper_pushes, num_r_sweeps, num_r_overhead_pushes):

    rospy.loginfo("Getting table pose")
    table_req = LocateTableRequest()
    table_req.recalculate = True
    raise_req = RaiseAndLookRequest()
    try:
        table_res = self.table_proxy(table_req);
    except rospy.ServiceException as e:
        rospy.logwarn("Service did not process request: %s"%str(e))
        return
    raise_req.table_centroid = table_res.table_centroid

    rospy.loginfo("Raising spine");
    raise_res = self.raise_and_look_push_proxy(raise_req)

    rospy.loginfo("Pushing shit");
    for i in range(num_l_gripper_pushes):
        self.gripper_push_object(self.gripper_push_dist, 'l')
    for i in range(num_r_gripper_pushes):
        self.gripper_push_object(self.gripper_push_dist, 'r')
    for i in range(num_l_sweeps):
        self.sweep_object(self.gripper_sweep_dist, 'l')
    for i in range(num_r_sweeps):
        self.sweep_object(self.gripper_sweep_dist, 'r')
    for i in range(num_l_overhead_pushes):
        self.overhead_push_object(self.overhead_push_dist, 'l')
    for i in range(num_r_overhead_pushes):
        self.overhead_push_object(self.overhead_push_dist, 'r')

def citable_repository( self, trans, owner, name ): 
    """Support for citeable URL for each repository, e.g. http://example.org/view/owner/name.""" 
    try: 
        repository = suc.get_repository_by_name_and_owner( trans.app, name, owner ) 
    except: 
        repository = None 
    if repository: 
        repository_id = trans.security.encode_id( repository.id ) 
        return trans.fill_template( "/webapps/community/citable_repository.mako", 
                                    repository_id=repository_id ) 
    else: 
        repositories = suc.get_repositories_by_owner( trans.app, owner ) 
        if repositories: 
            # Logic to display repositories can be added here 
            return trans.fill_template( "/webapps/community/owner_repositories.mako", 
                                         repositories=repositories ) 
        message = "No repositories named <b>%s</b> with owner <b>%s</b> exist." % ( str( name ), str( owner ) ) 
        return trans.response.send_redirect( web.url_for( controller='repository', 
                                                          action='browse_categories', 
                                                          id=None, 
                                                          name=None, 
                                                          owner=None, 
                                                          message=message, 
                                                          status='error' ) )

