def get_delphi_arrays(self):
    arrays = 'type\n'
    types = {}\n
    for packet in self.get_packets():
        for element in packet.get_elements():
            if element.get_type() == 'string' or element.get_cardinality() < 2:
                continue\n
            delphi_type = element.get_delphi_type()
            left = 'TArray0To{0}Of{1}'.format(element.get_cardinality() - 1, delphi_type[1])
            right = 'array [0..{0}] of {1}'.format(element.get_cardinality() - 1, delphi_type[0])
            types[left] = right\n
    if len(types) > 0:
        for left in types:
            arrays += '  {0} = {1};\n'.format(left, types[left])\n
        arrays += '\n'\n
    has_high_level_callback_states = False\n
    for packet in self.get_packets('callback'):
        if not packet.has_high_level():
            continue\n
        stream_out = packet.get_high_level('stream_out')\n
        if not stream_out:
            continue\n
        has_high_level_callback_states = True
        callback_state_data_delphi_type = None
        callback_state_length_delphi_type = None\n
        for element in packet.get_elements(direction='out'):
            role = element.get_role()\n
            if not role:
                continue\n
            if role.endswith('length'):
                callback_state_length_delphi_type = element.get_delphi_type()[0]\n
            if role.endswith('data'):
                callback_state_data_delphi_type = element.get_delphi_type()[0]\n
                if stream_out.get_fixed_length():
                    callback_state_length_delphi_type = 'word' if stream_out.get_fixed_length() else callback_state_length_delphi_type\n
        arrays += \
            '  T{0}HighLevelCallbackState = record data: array of {1}; length: {2}; end;\n'.format(packet.get_camel_case_name(skip=-2),
                                                                                                   callback_state_data_delphi_type,
                                                                                                   callback_state_length_delphi_type)\n
    arrays += '\n'\n
    for dt in delphi_common.delphi_types:
        arrays += '  TArray{0} = array of {1};\n'.format(delphi_common.delphi_types[dt][0].capitalize(),
                                                         delphi_common.delphi_types[dt][0])\n
    if has_high_level_callback_states:
        arrays += '\n'\n
    return arrays

