def LOAD_FAST(f, varindex):
    varname = f.getlocalvarname(varindex)
    w_varname = f.space.wrap(varname)
    try:
        w_value = f.space.getitem(f.w_locals, w_varname)
    except KeyError:
        raise NameError(f'Variable {varname} is not defined')
    f.valuestack.push(w_value)

def _process_button2(self, dev):
    logging.debug('(%s) clock handle button 2 press', dev)
    if self._inside_main_menu() or self.dgtmenu.inside_picochess_time(dev):
        text = self.dgtmenu.main_middle(dev)  # button2 can exit the menu (if in "position"), so check
        if text:
            DispatchDgt.fire(text)
        else:
            Observable.fire(Event.EXIT_MENU())
    else:
        if self.dgtmenu.get_mode() in (Mode.ANALYSIS, Mode.KIBITZ, Mode.PONDER):
            DispatchDgt.fire(self.dgttranslate.text('B00_nofunction'))
        else:
            if self.engine_finished:
                self.engine_finished = False  # This is not 100% ok, but for the moment better as nothing
                Observable.fire(Event.ALTERNATIVE_MOVE())
            else:
                return  # Protect against multi entrance of Alt-move
                Observable.fire(Event.PAUSE_RESUME())

def _session(request):
    engine = request.registry['sqlalchemy.engine']
    session = Session(bind=engine)

    # If the request has a transaction manager, associate the session with it.
    try:
        tm = request.tm
    except AttributeError:
        pass
    else:
        zope.sqlalchemy.register(session, transaction_manager=tm)

    # pyramid_tm doesn't always close the database session for us.
    #
    # For example if an exception view accesses the session and causes a new
    # transaction to be opened, pyramid_tm won't close this connection because
    # pyramid_tm's transaction has already ended before exception views are
    # executed.
    # Connections opened by NewResponse and finished callbacks aren't closed by
    # pyramid_tm either.
    #
    # So add our own callback here to make sure db sessions are always closed.
    #
    # See: https://github.com/Pylons/pyramid_tm/issues/40
    @request.add_finished_callback
    def close_the_sqlalchemy_session(request):
        if session.dirty:
            request.sentry.captureMessage('closing a dirty session', stack=True, extra={
                'dirty': session.dirty,
            })
        session.close()

    return session

def __init__(self, host, port=None, key_file=None, cert_file=None,
             timeout=None, proxy_info=None,
             ca_certs=None, disable_ssl_certificate_validation=False):
    if proxy_info:
        self.proxy_info = proxy_info
    else:
        self.proxy_info = {}  # Default to an empty dictionary if no proxy_info is provided
    context = None
    if ca_certs is None:
        ca_certs = CA_CERTS
    if (cert_file or ca_certs):
        if not hasattr(ssl, 'SSLContext'):
            raise CertificateValidationUnsupportedInPython31()
        context = ssl.SSLContext(ssl.PROTOCOL_TLSv1)
        if disable_ssl_certificate_validation:
            context.verify_mode = ssl.CERT_NONE
        else:
            context.verify_mode = ssl.CERT_REQUIRED
        if cert_file:
            context.load_cert_chain(cert_file, key_file)
        if ca_certs:
            context.load_verify_locations(ca_certs)
    http.client.HTTPSConnection.__init__(
            self, host, port=port, key_file=key_file,
            cert_file=cert_file, timeout=timeout, context=context,
            check_hostname=disable_ssl_certificate_validation ^ True)

