def __iter__(self):
    if hasattr(self, 'glue') and self.glue:
        for i, component in enumerate(self._components):
            yield component
            if (i + 1) % 2 == 0:
                yield self.glue
    else:
        return iter(self._components)

def __iter__(self):
    for index, component in enumerate(self._components):
        if index % 2 == 1:
            yield 'glue'
        yield component

def do_sample(sample_obj, rest, count, full_olist):
    samples = [("cycles:pp", "Precise cycles", )]

    def sample_list(obj):
        return [(s, obj.name) for s in obj.sample]

    for obj in sample_obj:
        if len(obj.sample) == 0:
            m = full_name(obj) + "*"
            csamples = flatten([sample_list(o)
                                    for o in full_olist
                                    if fnmatch.fnmatch(full_name(o), m) and o.level <= obj.level + SAMPLE_EXTEND])
            if len(csamples) > 2:
                print("Many possible sample events in deeper nodes.")
                print("Consider remeasuring with --nodes '+%s*' to narrow down" % obj.name)
            samples += [s for s in csamples if s[1] == obj.name and s[0].level <= obj.level + SAMPLE_EXTEND]
            continue
        for s in obj.sample:
            samples.append((s, obj.name))
    nsamp = [x for x in samples if not unsup_event(x[0], unsup_events)]
    nsamp = [(remove_pp(x[0]), x[1])
             if unsup_event(x[0], unsup_pebs) else x
             for x in nsamp]
    if nsamp != samples:
        missing = [x[0] for x in set(samples) - set(nsamp)]
        if not args.quiet:
            print("warning: update kernel to handle sample events:", file=sys.stderr)
            print("\n".join(missing), file=sys.stderr)

    def force_pebs(ev):
        return ev.startswith("FRONTEND_") or ("PREC_DIST" in ev)

    no_pebs = not supports_pebs()
    if no_pebs:
        nsamp = [x for x in nsamp if not force_pebs(x[0])]
    sl = [raw_event(s[0], s[1] + "_" + clean_event(s[0]), period=True, nopebs=False) for s in nsamp]
    sl = add_filter(sl)
    sample = ",".join([x for x in sl if x])
    if no_pebs:
        sample = re.sub(r'/p+', '/', sample)
        sample = re.sub(r':p+', '', sample)
    print("Sampling:")
    extra_args = args.sample_args.replace("+", "-").split()
    perf_data = args.sample_basename
    if count:
        perf_data += ".%d" % count
    sperf = [perf, "record"] + extra_args + ["-e", sample, "-o", perf_data] + [x for x in rest if x != "-A"]
    print(" ".join(sperf))
    if args.run_sample:
        ret = os.system(" ".join(sperf))
        if ret:
            print("Sampling failed")
            sys.exit(1)
        if not args.quiet:
            print("Run `" + perf + " report %s%s' to show the sampling results" % (
                ("-i %s" % perf_data) if perf_data != "perf_data" else "",
                " --no-branch-history" if "-b" in extra_args else ""))

def build(self, keep_going='0'):
  """Execute the build.ninja file."""
  # -k N     keep going until N jobs fail (0 means infinity)
  # -C DIR   change to DIR before doing anything else
  return subprocess.call(
      ['ninja', '-k', keep_going, '-C', os.path.dirname(self.ninja_file)])

