            _("This package must be installed in an EdX environment to look up configuration.")
        )

    return reverse(
        'enterprise_program_enrollment_page',
        kwargs={'enterprise_uuid': self.uuid, 'program_uuid': program_uuid}
    )

def tasks(self, kpi_id, recent_only=False):
    ''' Return a list of open issues that refer to the kpi id. '''
    def browse_url(issue):
        ''' Return a url that points to the issue. '''
        return self.__url + 'browse/' + issue['key']

    def match_id(issue, kpi_id):
        ''' Return whether the issue refers to the KPI. '''
        return 'KPI %s' % kpi_id in issue['fields']['description']

    def match_recent(issue):
        ''' Return whether the issue is recent. '''
        if recent_only:
            date_time_string = issue['fields']['updated']
            updated = utils.parse_iso_date_time(date_time_string)
            age = datetime.datetime.now() - updated
            return age < datetime.timedelta(weeks=4)  # Changed magic constant to 4 weeks
        else:
            return True

    return [browse_url(issue) for issue in self.__all_tasks() \
            if match_id(issue, kpi_id) and match_recent(issue)]

def ext_tasks_search(request):
    resp = {}
    if request.method != "POST":
        resp = {"error": True, "error_value": "Method not allowed"}
        return jsonize(resp, response=True)

    if not apiconf.extendedtasksearch.get("enabled"):
        resp = {"error": True, "error_value": "Extended Task Search API is Disabled"}
        return jsonize(resp, response=True)

    term = request.POST.get("option", "")
    value = request.POST.get("argument", "")

    if term and value:
        records = False
        if not term in search_term_map.keys() and term not in ("malscore", "ttp"):
            resp = {"error": True, "error_value": "Invalid Option. '%s' is not a valid option." % term}
            return jsonize(resp, response=True)

        if term == "ids":
            if all([v.strip().isdigit() for v in value.split(",")]):
                value = [int(v.strip()) for v in filter(None, value.split(","))]
            else:
                return jsonize({"error": True, "error_value": "Not all values are integers"}, response=True)
        try:
            if term == "malscore":
                records = perform_malscore_search(value)
            elif term == "ttp":
                records = perform_ttps_search(value)
            else:
                records = perform_search(term, value)
        except ValueError:
            if not term:
                resp = {"error": True, "error_value": "No option provided."}
            if not value:
                resp = {"error": True, "error_value": "No argument provided."}
            if not term and not value:
                resp = {"error": True, "error_value": "No option or argument provided."}

        if records:
            ids = list()
            for results in records:
                if repconf.mongodb.enabled:
                    ids.append(results)
                if es_as_db:
                    ids.append(results["_source"])
            if term == "ids":
                task_details = {task.id: task.status for task in db.list_tasks(task_ids=value) or []}
                for block in ids:
                    if block["info"]["id"] in task_details:
                        block["status"] = task_details[block["info"]["id"]]
            resp = {"error": False, "data": ids}
        else:
            resp = {"error": True, "error_value": "Unable to retrieve records"}
    else:
        if not term:
            resp = {"error": True, "error_value": "No option provided."}
        if not value:
            resp = {"error": True, "error_value": "No argument provided."}
        if not term and not value:
            resp = {"error": True, "error_value": "No option or argument provided."}

    return jsonize(resp, response=True)

def _sync_step_from_queue(self, step):
    try:
        item = self._get_json_response(
            step.data['master'],
            '/queue/item/{}'.format(step.data['item_id']),
        )
    except NotFound:
        # Attempt to scrape the list of jobs for a matching CHANGES_BID
        # This doesn't explicitly mean that the job doesn't exist.
        self._attempt_scrape_for_matching_changes_bid(step)
        return

    if item.get('executable'):
        build_no = item['executable']['number']
        step.data['queued'] = False
        step.data['build_no'] = build_no
        step.data['uri'] = item['executable']['url']
        db.session.add(step)

    if item['blocked']:
        step.status = Status.queued
        db.session.add(step)
    elif item.get('cancelled') and not step.data.get('build_no'):
        step.status = Status.finished
        step.result = Result.aborted
        db.session.add(step)
    elif item.get('executable'):
        return self._sync_step_from_active(step)

    def _attempt_scrape_for_matching_changes_bid(self, step):
        # Logic to scrape the list of jobs for a matching CHANGES_BID
        pass

def _save_checkpoint(self, training_state, phase="main", new_best_macro=False, keep_all=False):
    """
    Parameters
    ----------
    training_state: An object containing trainer state (step number, etc.), to be saved.
    phase: Usually 'main' or 'eval'.
    new_best_macro: If true, the saved checkpoint will be marked with .best_macro, and
        potentially used later when switching from main to eval training.
    """
    if not self._serialization_dir:
        raise ConfigurationError("serialization_dir not specified - cannot "
                                 "restore a model without a directory path.")

    epoch = training_state["epoch"]
    if phase == "eval":
        model_path = os.path.join(
            self._serialization_dir,
            "model_state_eval_best.th")
    else:
        best_str = ".best_macro" if new_best_macro else ""
        model_path = os.path.join(
            self._serialization_dir,
            "model_state_{}_epoch_{}{}.th".format(
                phase, epoch, best_str))

    model_state = self._model.state_dict()

    keys_to_skip = [key for key in model_state if dont_save(key)]
    for key in keys_to_skip:
        del model_state[key]
    torch.save(model_state, model_path)

    if phase != "eval":
        torch.save(
            training_state,
            os.path.join(
                self._serialization_dir,
                "training_state_{}_epoch_{}{}.th".format(
                    phase, epoch, best_str)))

        task_states = {}
        for task_name, task_info in self._task_infos.items():
            task_states[task_name] = {
                'total_batches_trained': task_info['total_batches_trained'],
                'stopped': task_info['stopped'],
                'optimizer': task_info['optimizer'].state_dict(),
                'scheduler': {}
            }
        task_states['global'] = {
            'optimizer': self._g_optimizer.state_dict() if self._g_optimizer is not None else None,
            'scheduler': {}
        }
        if self._g_scheduler is not None:
            sched = self._g_scheduler
            task_states['global']['scheduler'] = {}
        else:
            task_states['global']['scheduler'] = None
        torch.save(task_states, os.path.join(self._serialization_dir,
                                             "task_state_{}_epoch_{}{}.th".format(
                                                 phase, epoch, best_str)))

        metric_states = {}
        for metric_name, metric_info in self._metric_infos.items():
            metric_states[metric_name] = {
                'hist': metric_info['hist'],
                'stopped': metric_info['stopped'],
                'best': metric_info['best']
            }
        torch.save(
            metric_states,
            os.path.join(
                self._serialization_dir,
                "metric_state_{}_epoch_{}{}.th".format(
                    phase, epoch, best_str)))
    log.info("Saved files to %s", self._serialization_dir)

    if phase != "eval" and new_best_macro:
        self._unmark_previous_best(phase, epoch)

    if not self._keep_all_checkpoints:
        self._delete_old_checkpoints(phase, epoch)

