def schedule(self, seen=None) -> List[ScheduleItem]:
  if seen is None: seen = set()
  if self in seen or self.realized or self.is_unrealized_const(): return []
  seen.add(self)
  if self.base != self: return self.base.schedule(seen)

  # rewrite unbased CONTIGUOUS into UnaryOps.NOOP
  op = self.op if self.op.op != LoadOps.CONTIGUOUS else LazyOp(UnaryOps.NOOP, self.op.src)

  if self.optype is BinaryOps: op = _ast_binaryops(op, self.shape)
  elif self.optype is ReduceOps: op = _ast_reduceops(op)

  # realize the past and exec the AST
  ret = []
  for x in op.buffers: ret += x.schedule(seen)

  # merge variable values into the schedule
  self.var_vals = dict(sorted(merge_dicts([self.var_vals] + [buf.var_vals for buf in op.buffers]).items(), key=lambda kv:cast(Variable,kv[0]).key))

  # run the ast and log the op
  op, base_bufs = _replace_bufferops(op)
  return ret + [ScheduleItem(op, self, tuple(base_bufs))]

def build_pipeline(
    path: PathLike, synonym_table_cache: SynonymTableCache, labels: List[str]
) -> spacy.language.Language:
    synonym_table_paths = synonym_table_cache.get_synonym_table_paths()
    return assemble_pipeline(
        parquet_files=synonym_table_paths,
        labels=labels,
        span_key=config.get('span_key'),
        output_dir=path,
    )

def downloadPkgs(self, pkglist, callback=None):
    """download list of package objects handed to you, output based on
       callback, raise yum.Errors.YumBaseError on problems"""

    errors = {}
    self.plugins.run('predownload', pkglist=pkglist)
    repo_cached = False
    remote_pkgs = []
    for po in pkglist:
        if hasattr(po, 'pkgtype') and po.pkgtype == 'local':
            continue

        local = po.localPkg()
        if os.path.exists(local):
            cursize = os.stat(local)[6]
            totsize = int(po.size)
            try:
                result = self.verifyPkg(local, po, raiseError=1)
            except URLGrabError, e: # fails the check

                repo = self.repos.getRepo(po.repoid)
                if repo.cache:
                    repo_cached = True
                    msg = 'package fails checksum but caching is enabled for %s' % repo.id
                    if not errors.has_key(po): errors[po] = []
                    errors[po].append(msg)

                if cursize >= totsize: # keep it around for regetting
                    os.unlink(local)

            else:
                if result:
                    continue
                else:
                    if cursize >= totsize: # keep it around for regetting
                        os.unlink(local)
        remote_pkgs.append(po)

        # caching is enabled and the package
        # just failed to check out there's no
        # way to save this, report the error and return
        if (self.conf.cache or repo_cached) and errors:
            return errors


    i = 0
    for po in remote_pkgs:
        i += 1
        repo = self.repos.getRepo(po.repoid)
        checkfunc = (self.verifyPkg, (po, 1), {})


        # Check for available disk space
        if os.statvfs(repo.localpath).f_bavail * os.statvfs(repo.localpath).f_frsize < po.size:
            raise Exception('Not enough disk space to download the package: %s' % os.path.basename(po.returnSimple('relativepath')))

        try:
            text = '(%s/%s): %s' % (i, len(remote_pkgs),
                                    os.path.basename(po.returnSimple('relativepath')))
            mylocal = repo.getPackage(po,
                               checkfunc=checkfunc,
                               text=text,
                               cache=repo.http_caching != 'none',
                               )
        except Errors.RepoError, e:
            if not errors.has_key(po):
                errors[po] = []
            errors[po].append(str(e))
        else:
            po.localpath = mylocal
            if errors.has_key(po):
                del errors[po]

    self.plugins.run('postdownload', pkglist=pkglist, errors=errors)

    return errors

