    return errors

def free_energy(self, v_sample):
    h_mean = T.nnet.sigmoid(T.dot(v_sample, self.W) + self.hbias)
    stable_log_h_mean = T.log(T.clip(h_mean, 1e-10, 1 - 1e-10))
    return -T.sum(stable_log_h_mean) - T.sum(T.dot(v_sample, self.vbias))

def _append_required_defaults(self, kwargs, algorithm_inputs):
    """
    Add if necessary any parameters marked as required that have a default value
    in the algorithm interface but were not submitted from the UI. For example in
    operations launched from context-menu or from data structure.
    """
    if algorithm_inputs is None:
        return

    for entry in algorithm_inputs:
        ## First handle this level of the tree, adding defaults where required
        if (entry[self.KEY_NAME] not in kwargs
                and entry.get(self.KEY_REQUIRED) is True
                and self.KEY_DEFAULT in entry
                and entry[self.KEY_TYPE] != xml_reader.TYPE_DICT):
            kwargs[entry[self.KEY_NAME]] = entry[self.KEY_DEFAULT]

    for entry in algorithm_inputs:
        ## Now that first level was handled, go recursively on selected options only
        if entry.get(self.KEY_REQUIRED) is True and entry.get(ABCAdapter.KEY_OPTIONS) is not None:
            for option in entry[ABCAdapter.KEY_OPTIONS]:
                #Only go recursive on option that was submitted
                if option[self.KEY_VALUE] == kwargs[entry[self.KEY_NAME]] and ABCAdapter.KEY_ATTRIBUTES in option:
                    option[ABCAdapter.KEY_ATTRIBUTES] = self._append_required_defaults(kwargs, option[self.KEY_ATTRIBUTES]) or {}

def _key_press(self, alt_mask, keyname, keyunicode):
    if keyname is None:
        return False

    self.keypress = keyname

    if alt_mask:
        if keyname == "p":
            self.hideshow_button()
        elif keyname == 'q':
            self.quit_plugins()
            if self.gst_available:
                stop_media(self.lc)
            exit()
        elif keyname == 'g':
            self._align_to_grid()

    elif self.selected_blk is not None:
        if self.selected_blk.name == 'number':
            self._process_numeric_input(keyname)
        elif self.selected_blk.name == 'string':
            self.process_alphanumeric_input(keyname, keyunicode)
            self.selected_blk.resize()
        elif self.selected_blk.name != 'proto':
            self._process_keyboard_commands(keyname, block_flag=True)

    elif self.turtles.spr_to_turtle(self.selected_spr) is not None:
        self._process_keyboard_commands(keyname, block_flag=False)

    return True

def test_cached_microdesc_consensus(self):
  """
  Parses the cached-microdesc-consensus file in our data directory.
  """

  consensus_path = test.runner.get_runner().get_test_dir('cached-microdesc-consensus')

  if not os.path.exists(consensus_path):
    test.runner.skip(self, '(no cached-microdesc-consensus)')
    return
  elif stem.util.system.is_windows():
    test.runner.skip(self, '(unavailable on windows)')
    return

  count = 0
  with open(consensus_path, 'rb') as descriptor_file:
    for router in stem.descriptor.parse_file(descriptor_file, 'network-status-microdesc-consensus-3 1.0', validate = True):
      count += 1

      # check if there's any unknown flags
      for flag in router.flags:
        if flag not in stem.Flag:
          raise ValueError('Unrecognized flag type: %s, found on microdescriptor relay %s (%s)' % (flag, router.fingerprint, router.nickname))

      unrecognized_lines = router.get_unrecognized_lines()

      if unrecognized_lines:
        self.fail('Unrecognized descriptor content: %s' % unrecognized_lines)

  self.assertTrue(count > 100)

