def submission(request, username=None):
    if request.method == 'HEAD':
        # Implement Http Digest Authentication here
        return OpenRosaResponse(status=204)
    context = RequestContext(request)
    xml_file_list = []
    media_files = []
    html_response = False
    try:
        xml_file_list = request.FILES.pop("xml_submission_file", [])
        if len(xml_file_list) != 1:
            return OpenRosaResponseBadRequest(
                _(u"There should be a single XML submission file.")
            )
        media_files = request.FILES.values()
        uuid = request.POST.get('uuid')
        if not username and uuid:
            html_response = True
        try:
            instance = create_instance(
                username,
                xml_file_list[0],
                media_files,
                uuid=uuid
            )
        except InstanceInvalidUserError:
            return OpenRosaResponseBadRequest(_(u"Username or ID required."))
        except IsNotCrowdformError:
            return OpenRosaResponseNotAllowed(
                _(u"Sorry but the crowd form you submitted to is closed.")
            )
        except InstanceEmptyError:
            return OpenRosaResponseBadRequest(
                _(u"Received empty submission. No instance was created")
            )
        except FormInactiveError:
            return OpenRosaResponseNotAllowed(_(u"Form is not active"))
        except XForm.DoesNotExist:
            return OpenRosaResponseNotFound(
                _(u"Form does not exist on this account")
            )
        except ExpatError:
            return OpenRosaResponseBadRequest(_(u"Improperly formatted XML."))
        except DuplicateInstance:
            response = OpenRosaResponse(_(u"Duplicate submission"))
            response.status_code = 202
            response['Location'] = request.build_absolute_uri(request.path)
            return response

        if instance is None:
            return OpenRosaResponseBadRequest(
                _(u"Unable to create submission."))

        audit = {
            "xform": instance.xform.id_string
        }
        audit_log(Actions.SUBMISSION_CREATED, request.user, instance.xform.user,
            _("Created submission on form %(id_string)s.") %\
            {
                "id_string": instance.xform.id_string
            }, audit, request)
        if html_response:
            context.username = instance.user.username
            context.id_string = instance.xform.id_string
            context.domain = Site.objects.get(id=settings.SITE_ID).domain
            response = render_to_response("submission.html",
                                          context_instance=context)
        else:
            response = OpenRosaResponse()
        response.status_code = 201
        response['Location'] = request.build_absolute_uri(request.path)
        return response
    except IOError as e:
        if 'request data read error' in unicode(e):
            return OpenRosaResponseBadRequest(
                _(u"File transfer interruption."))
        else:
            raise
    finally:
        if len(xml_file_list):
            [_file.close() for _file in xml_file_list]
        if len(media_files):
            [_file.close() for _file in media_files]

def _populate_scores_dict(self, bss_output):

    self.scores[self.RAW_VALUES] = dict(bss_output.json)  # Hack to format dict correctly
    self.scores[self.SDR_MEANS] = self._get_mean_scores(repr(bss_output))

def update_interface(self, data):
    """
    Update XPON interfaces
    :param data: (xpon config info)
    """
    name = data.name
    interface = data.interface
    inst_data = data.data

    items = self._get_xpon_collection(data)

    if items is None:
        raise ValueError('Unknown data type: {}'.format(type(data)))

    existing_item = items.get(name)
    if existing_item is None:
        raise KeyError("'{}' not found. Type: {}".format(name, type(data)))

    item_type, update_item = self._data_to_dict(data)
    self.log.debug('update-item', item_type=item_type, item=update_item)

    # Calculate the difference
    diffs = {k: update_item[k] for k in update_item if update_item[k] != existing_item.get(k)}

    if len(diffs) == 0:
        self.log.debug('update-item-no-diffs')

    self._cached_xpon_pon_info = {}     # Clear cached data

    # Act on changed items
    if isinstance(data, ChannelgroupConfig):
        pass

    elif isinstance(data, ChannelpartitionConfig):
        pass

    elif isinstance(data, ChannelpairConfig):
        pass

    elif isinstance(data, ChannelterminationConfig):
        pass

    elif isinstance(data, OntaniConfig):
        pass

    elif isinstance(data, VOntaniConfig):
        pass

    elif isinstance(data, VEnetConfig):
        pass

    else:
        raise NotImplementedError('Unknown data type')

    raise NotImplementedError('TODO: not yet supported')

