def test_device(self):
    devices = Device.objects.all()  # Allow multiple devices
    device_ids = [device.pk for device in devices]
    params = {'device_id': device_ids}
    self.assertEqual(self.filterset(params, self.queryset).qs.count(), 2)
    device_names = [device.name for device in devices]
    params = {'device': device_names}
    self.assertEqual(self.filterset(params, self.queryset).qs.count(), 2)

def _tracing_name(module):
  if not _TRACED_STACK_MODULES:
      return None

  def _extract_child_recursively(module, prefix, name_to_child=None):
    if name_to_child is None:
      name_to_child = {}

    # If the child is a ModuleList,
    # we need to use the child in the list as the actual child.
    if isinstance(module, ModuleList):
      for index, child in enumerate(module):
        # Add missing hierarchy to the name so that
        # we can fetch the corresponding module by the name.
        # Note that the odd child name is meant to match the
        # string concatenatation in _set_trace_module_map.
        child_name = f"{prefix}/ModuleList[{index}]"
        _extract_child_recursively(child, child_name, name_to_child)
    else:
      name_to_child[prefix] = module
    return name_to_child

  name_to_child = {}
  parent = _TRACED_STACK_MODULES[-1]
  for name, child in parent.named_children():
    _extract_child_recursively(child, name, name_to_child)

  for name, child in name_to_child.items():
    if child is module:
      return name
  return None

def _resolve_descriptors(self, name, types):
    """Processes descriptors"""
    name_scope = name.get_definition().get_parent_scope()
    if not isinstance(name_scope, (er.Instance, pr.Class)):
        return types

    result = []
    for r in types:
        try:
            desc_return = r.get_descriptor_returns
        except AttributeError:
            result.append(r)
        else:
            result += desc_return(self.scope)

    return result

def __setitem__(self, item: Union[slice, str], value):
    if isinstance(item, str):
        if isinstance(value, np.ndarray):
            self.tensors[item] = Tensor(item)
            return self.tensors[item]
        else:
            raise UnsupportedTensorTypeError(item)
    else:
        raise InvalidKeyTypeError(item)

def on_key_press(self, event):
    """Called whenever key pressed in canvas."
    """
    if event.native.isAutoRepeat() or event.key is None:
        return

    comb = components_to_key_combo(event.key.name, event.modifiers)

    layer = self.viewer.active_layer

    if layer is not None and comb in layer.keymap:
        parent = layer
    elif comb in self.viewer.keymap:
        parent = self.viewer
    else:
        return

    func = parent.keymap[comb]
    gen = func(parent)

    if inspect.isgeneratorfunction(func):
        try:
            next(gen)
        except StopIteration:  # only one statement
            pass
        else:
            self._key_release_generators[event.key] = gen

def load(source):
    data = yield from BytesType.load(source)
    return data.decode('utf-8', 'strict')

def __init__(self, name: str, *, consume: bool = False) -> None:
    self.name = name
    self.__reference_strategy = BundleReferenceStrategy(name, consume)

def blocker_search(self, status, search_filter='default', verbose=False, **kwargs):
    include_labels = ['release_blocker']
    query = self._query(
        status=status,
        include_labels=include_labels,
        target_release=self.target_release(),
        search_filter=search_filter
    )
    return self._search(query, verbose=verbose, **kwargs)

def setup_part2(self):

    self.info('running on host: %s' % self.hostname)
    if self.hostname.startswith('127.'):
        self.warning('detection of own ip failed, using %s as own address, functionality will be limited', self.hostname)

    unittest = self.config.get('unittest', 'no')
    if unittest == 'no':
        unittest = False
    else:
        unittest = True

    self.ssdp_server = SSDPServer(test=unittest)
    louie.connect( self.create_device, 'Coherence.UPnP.SSDP.new_device', louie.Any)
    louie.connect( self.remove_device, 'Coherence.UPnP.SSDP.removed_device', louie.Any)
    louie.connect( self.add_device, 'Coherence.UPnP.RootDevice.detection_completed', louie.Any)
    #louie.connect( self.receiver, 'Coherence.UPnP.Service.detection_completed', louie.Any)

    self.ssdp_server.subscribe("new_device", self.add_device)
    self.ssdp_server.subscribe("removed_device", self.remove_device)

    self.msearch = MSearch(self.ssdp_server,test=unittest)

    reactor.addSystemEventTrigger( 'before', 'shutdown', self.shutdown, force=True)

    self.web_server = WebServer( self.config.get('web-ui',None), self.web_server_port, self)

    self.urlbase = 'http://%s:%d/' % (self.hostname, self.web_server_port)

    #self.renew_service_subscription_loop = task.LoopingCall(self.check_devices)
    #self.renew_service_subscription_loop.start(20.0, now=False)

    self.available_plugins = None

    self.ctrl = None

    try:
        plugins = self.config['plugin']
        if isinstance(plugins,dict):
            plugins=[plugins]
    except:
        plugins = None
    if plugins is None:
        plugins = self.config.get('plugins',None)

    if plugins is None:
        self.info("No plugin defined!")
    else:
        if isinstance(plugins,dict):
            for plugin,arguments in plugins.items():
                try:
                    if not isinstance(arguments, dict):
                        arguments = {}
                    self.add_plugin(plugin, **arguments)
                except Exception, msg:
                    self.warning("Can't enable plugin, %s: %s!" % (plugin, msg))
                    self.info(traceback.format_exc())
        else:
            for plugin in plugins:
                try:
                    if plugin['active'] == 'no':
                        continue
                except (KeyError,TypeError):
                    pass
                try:
                    backend = plugin['backend']
                    arguments = copy.copy(plugin)
                    del arguments['backend']
                    backend = self.add_plugin(backend, **arguments)
                    if self.writeable_config() == True:
                        if 'uuid' not in plugin:
                            plugin['uuid'] = str(backend.uuid)[5:]
                            self.config.save()
                except Exception, msg:
                    self.warning("Can't enable plugin, %s: %s!" % (plugin, msg))
                    self.info(traceback.format_exc())

    if self.config.get('controlpoint', 'no') == 'yes':
        self.ctrl = ControlPoint(self)

    if self.config.get('use_dbus', 'no') == 'yes':
        try:
            from coherence import dbus_service
            if self.ctrl == None:
                self.ctrl = ControlPoint(self)
            self.dbus = dbus_service.DBusPontoon(self.ctrl)
        except Exception, msg:
            self.warning("Unable to activate dbus sub-system: %r" % msg)
            self.debug(traceback.format_exc())
        else:
            if self.config.get('enable_mirabeau', 'no') == 'yes':
                from coherence.dbus_constants import BUS_NAME, DEVICE_IFACE, SERVICE_IFACE
                from coherence.extern.telepathy import connect
                from coherence.extern.telepathy.mirabeau_tube_publisher import MirabeauTubePublisher
                chatroom = self.config.get('chatroom', 'UPnPProxy')
                manager = self.config.get('manager', 'salut')
                protocol = self.config.get('protocol', 'local-xmpp')
                account = {'first-name': 'player', 'last-name':'', 'nickname':'player',
                           'published-name':'player'}
                connection = connect.tp_connect(manager, protocol, account)
                tubes_to_offer = {BUS_NAME: {}, DEVICE_IFACE: {}, SERVICE_IFACE: {}}
                self._tube_publisher = MirabeauTubePublisher(connection, chatroom,
                                                             tubes_to_offer, self)
                self._tube_publisher.start()

