def _create_lib_latest(self):
    """Create the lib_latest symlink for App Builder."""
    if platform.system() == 'Windows':
        import shutil
        src = 'lib_{}'.format(self.latest_version)
        dst = self.static_lib_dir
        if os.path.exists(dst):
            shutil.rmtree(dst)
        shutil.copytree(src, dst)
    else:
        if os.path.islink(self.static_lib_dir):
            os.unlink(self.static_lib_dir)
        os.symlink('lib_{}'.format(self.latest_version), self.static_lib_dir)

def _create_lib_latest(self):
    """Create the lib_latest symlink for App Builder."""
    if platform.system() == 'Windows':
        import shutil
        shutil.copytree('lib_{}'.format(self.latest_version), self.static_lib_dir, dirs_exist_ok=True)
    else:
        if os.path.islink(self.static_lib_dir):
            os.unlink(self.static_lib_dir)
        os.symlink('lib_{}'.format(self.latest_version), self.static_lib_dir)

def rm_old_files(rootdir, excludes=None, includes=None,
                 expire_time=(30 * DAY)):
    """Nuke everything under '''rootdir''' that doesn't match
       '''exclude''' that's older than '''expire_time'''.
    """

    if excludes is None:
        excludes = []

    if includes is None:
        includes = []

    os.chdir(rootdir)

    expiration_date = time.time() - expire_time

    def is_wanted(path):
        return not any(fnmatch.fnmatch(path, pattern) for pattern in excludes) and \
               any(fnmatch.fnmatch(path, pattern) for pattern in includes)

    for path in filter(lambda e: os.stat(e).st_ctime < expiration_date and is_wanted(e),
                       os.listdir('.')):
        sys.stdout.write('Removing "%s/%s"\n' % (rootdir, path, ))
        if os.path.isdir(path):
            for root, __, files, in os.walk(path, topdown=False):
                for f in files:
                    os.unlink(os.path.join(root, f))
            os.rmdir(path)
        else:
            os.unlink(path)

def rm_old_files(rootdir, excludes=None, includes=None,
                 expire_time=(30 * DAY)):
    """Nuke everything under '''rootdir''' that doesn't match
       '''exclude''' that's older than '''expire_time'''.
    """

    if excludes is None:
        excludes = []

    if includes is None:
        includes = []

    os.chdir(rootdir)

    expiration_date = time.time() - expire_time

    for path in filter(lambda e: os.stat(e).st_ctime < expiration_date and not any(e.endswith(ext) for ext in includes),
                       os.listdir('.')):
        sys.stdout.write('Removing "%s/%s"\n' % (rootdir, path, ))
        if os.path.isdir(path):
            for root, __, files, in os.walk(path, topdown=False):
                for f in files:
                    os.unlink(os.path.join(root, f))
            os.rmdir(path)
        else:
            os.unlink(path)

def remove(self, docid_or_path_tuple):
    if isinstance(docid_or_path_tuple, int):
        path_tuple = self.docid_to_path[docid_or_path_tuple]
    elif isinstance(docid_or_path_tuple, tuple):
        path_tuple = docid_or_path_tuple
    else:
        raise ValueError(
            'remove accepts only a docid or a path tuple, got' % (
                docid_or_path_tuple,)
            )

    pathlen = len(path_tuple)

    dmap = self.pathindex.get(path_tuple)

    # rationale: if this key isn't present, no path added ever contained it
    if dmap is None:
        return set()

    removed = set()
    # sorted() only for clarity during tests
    items = sorted(dmap.items())

    # this can be done with a min= option to BTree.items method
    keys_to_delete = []
    for k, dm in self.pathindex.items():
        if k[:pathlen] == path_tuple:
            for didset in dm.values():
                removed.update(didset)
                for did in didset:
                    if did in self.docid_to_path:
                        p = self.docid_to_path[did]
                        del self.docid_to_path[did]
                        del self.path_to_docid[p]
            keys_to_delete.append(k)

    for k in keys_to_delete:
        del self.pathindex[k]

    for x in range(pathlen-1):
        offset = x + 1
        els = path_tuple[:pathlen-offset]
        dmap2 = self.pathindex.get(els)
        for level, didset in items:

            i = level + offset
            didset2 = dmap2.get(i)

            if didset2 is None:
                continue

            for did in didset:
                if did in didset2:
                    didset2.remove(did)
                    # adding to removed and removing from docid_to_path
                    # and path_to_docid should have been taken care of
                    # above in the for k, dm in self.pathindex.items()
                    # loop
                    assert did in removed, did
                    assert not did in self.docid_to_path, did

            if not didset2:
                del dmap2[i]

    return removed

