def _get_pod_unschedulable_reason(self, pod: KubernetesPod) -> PodUnschedulableReason:
    pod_resource_request = total_pod_resources(pod)
    for node_ip, pods_on_node in self._pods_by_ip.items():
        node = self._nodes_by_ip.get(node_ip)
        if node and pod_resource_request < total_node_resources(node) - allocated_node_resources(pods_on_node):
            return PodUnschedulableReason.Unknown

    return PodUnschedulableReason.InsufficientResources

def __init__(self, path, mode='r', schema=None, dshape=None,
             dialect=None, header=None, open=open, **kwargs):
    if 'r' in mode and os.path.isfile(path) is not True:
        raise ValueError('CSV file "%s" does not exist' % path)
    self.path = path
    self.mode = mode
    self.open = open

    if not schema and not dshape:
        # Infer schema from the file if not provided
        if os.path.exists(path):
            with self.open(path, 'r') as f:
                sample = f.read(1024)
            dshape = datashape.dshape(sample)
            if isinstance(dshape[0], datashape.Var):
                schema = dshape.subarray(1)
        if not schema:
            raise ValueError('No schema detected')
    if not schema and dshape:
        dshape = datashape.dshape(dshape)
        if isinstance(dshape[0], datashape.Var):
            schema = dshape.subarray(1)

    self._schema = schema

    if os.path.exists(path) and mode != 'w':
        with self.open(path, 'r') as f:
            sample = f.read(1024)
    else:
        sample = ''
    dialect = discover_dialect(sample, dialect, **kwargs)
    assert dialect
    if header is None:
        header = has_header(sample)

    self.header = header
    self.dialect = dialect

def __init__(self, path, mode='r', schema=None, dshape=None,
             dialect=None, header=None, open=open, **kwargs):
    if 'r' in mode and os.path.isfile(path) is not True:
        raise ValueError('CSV file "%s" does not exist' % path)
    self.path = path
