def _validate(self, efs_id, avail_zones_mapping: dict, are_all_security_groups_customized):
    for avail_zone, subnets in avail_zones_mapping.items():
        head_node_target_id = AWSApi.instance().efs.get_efs_mount_target_id(efs_id, avail_zone)
        # If there is an existing mt in the az, need to check the inbound and outbound rules of the security groups
        if head_node_target_id:
            # Get list of security group IDs of the mount target
            sg_ids = AWSApi.instance().efs.get_efs_mount_target_security_groups(head_node_target_id)
            if not _check_in_out_access(sg_ids, port=2049, is_cidr_optional=are_all_security_groups_customized):
                self._add_failure(
                    "There is an existing Mount Target {0} in the Availability Zone {1} for EFS {2}, "
                    "but it does not have a security group that allows inbound and outbound rules to support NFS. "
                    "Please modify the Mount Target's security group, to allow traffic on port 2049.".format(
                        head_node_target_id, avail_zone, efs_id
                    ),
                    FailureLevel.ERROR,
                )
            if not are_all_security_groups_customized:
                self._check_cidrs_cover_subnets(head_node_target_id, avail_zone, sg_ids, efs_id, subnets)
        else:
            if AWSApi.instance().efs.is_efs_standard(efs_id):
                self._add_failure(
                    "There is no existing Mount Target in the Availability Zone {0} for EFS {1}. "
                    "Please create an EFS Mount Target for the Availability Zone {0}.".format(avail_zone, efs_id),
                    FailureLevel.ERROR,
                )
            else:
                self._add_failure(
                    "EFS is in OneZone storage class, no mount target exists in {0} for EFS {1}.".format(avail_zone, efs_id),
                    FailureLevel.WARNING,
                )

def get_events(self):
    if self.session != self.get_current_session():
        raise Exception("Can't do that, dude")

    page = self.lxmlize("http://www.clevelandcitycouncil.org/calendar/")
    events = page.xpath("//ul[contains(@class, 'committee-events')]//li")
    for event in events:
        print(event)
        string = event.text_content()

        po = CLICK_INFO.match(event.xpath(".//span")[0].attrib['onclick'])
        if po is None:
            continue

        poid = po.groupdict()['info_id']  # This is used to get more deetz on

        popage = self.popOverUrl(poid)
        when = dt.datetime.strptime(popage.xpath("//strong")[0].text,
                                    "%B %d, %Y @ %I:%M %p")
        who = popage.xpath("//h1")[0].text
        related = []

        for item in popage.xpath("//div"):
            t = item.text
            if t is None:
                continue

            t = t.strip()
            for related_entity in ORD_INFO.findall(t):
                related.append({
                    "ord_no": related_entity,
                    "what": t
                })

        print(who, when, related)

def visit_Call(self, node):
    # Descend first
    self.generic_visit(node)

    func = node.func
    if not isinstance(func, ast.Name):
        return

    if func.id != '_':
        return

    for arg in node.args:
        # Check if arg is a BinOp of type Mod
        if isinstance(arg, ast.BinOp) and isinstance(arg.op, ast.Mod):
            return (node, "G102 Mod operator usage that may be acceptable")

        # Things like _("a" + "b") (including such constructs across line continuations
        if isinstance(arg, ast.BinOp) and isinstance(arg.op, ast.Add):
            return (node, "G100 string concatenation that will break xgettext")

        # Things like _(some_variable)
        if isinstance(arg, ast.Name):
            return (node, "G101 variable reference that will break xgettext")

