def convert_node_to_v6_json(node):
    """Returns the v6 JSON dict for the given node

    :param node: The node
    :type node: :class:`recipe.definition.node.NodeDefinition`
    :returns: The v6 JSON dict for the node
    :rtype: dict
    """

    dependencies = [{'name': name} for name in node.parents.keys()]

    input_dict = {}
    for connection in node.connections.values():
        if isinstance(connection, DependencyInputConnection):
            conn_dict = {'type': 'dependency', 'node': connection.node_name, 'output': connection.output_name}
        elif isinstance(connection, RecipeInputConnection):
            conn_dict = {'type': 'recipe', 'input': connection.recipe_input_name}
        input_dict[connection.input_name] = conn_dict

    if isinstance(node, ConditionNodeDefinition):
        interface_dict = convert_interface_to_v6_json(node.input_interface).get_dict()
        node_type_dict = {'node_type': 'condition', 'interface': interface_dict, 'recipe_condition': node.recipe_condition}
    elif isinstance(node, JobNodeDefinition):
        node_type_dict = {'node_type': 'job', 'job_type_name': node.job_type_name,
                          'job_type_version': node.job_type_version, 'job_type_revision': node.revision_num}
    elif isinstance(node, RecipeNodeDefinition):
        node_type_dict = {'node_type': 'recipe', 'recipe_type_name': node.recipe_type_name,
                          'recipe_type_revision': node.revision_num}

    node_dict = {'dependencies': dependencies, 'input': input_dict, 'node_type': node_type_dict}

    return node_dict

async def scala_bsp_dependency_modules(
    request: ScalaBSPDependencyModulesRequest,
    build_root: BuildRoot,
) -> BSPDependencyModulesResult:
    coarsened_targets = await Get(
        CoarsenedTargets, Addresses([fs.address for fs in request.field_sets])
    )
    resolve = await Get(CoursierResolveKey, CoarsenedTargets, coarsened_targets)
    lockfile = await Get(CoursierResolvedLockfile, CoursierResolveKey, resolve)

    transitive_targets = await Get(
        TransitiveTargets,
        TransitiveTargetsRequest(
            roots=[
                tgt.address
                for coarsened_target in coarsened_targets
                for tgt in coarsened_target.members
            ],
            include_special_cased_deps=True
        ),
    )

    artifact_requirements = [
        ArtifactRequirement.from_jvm_artifact_target(tgt)
        for tgt in transitive_targets.closure
        if JvmArtifactFieldSet.is_applicable(tgt)
    ]

    applicable_lockfile_entries: set[CoursierLockfileEntry] = set()
    for artifact_requirement in artifact_requirements:
        entry = get_entry_for_coord(lockfile, artifact_requirement.coordinate)
        if not entry:
            _logger.warning(
                f"No lockfile entry for {artifact_requirement.coordinate} in resolve {resolve.name}."
            )
            continue
        applicable_lockfile_entries.add(entry)

    resolve_digest = await Get(
        Digest,
        CreateDigest(
            [FileEntry(entry.file_name, entry.file_digest) for entry in applicable_lockfile_entries]
        ),
    )

    resolve_digest = await Get(
        Digest, AddPrefix(resolve_digest, f"jvm/resolves/{resolve.name}/lib")
    )

    modules = [
        DependencyModule(
            name=f"{entry.coord.group}:{entry.coord.artifact}",
            version=entry.coord.version,
            data=MavenDependencyModule(
                organization=entry.coord.group,
                name=entry.coord.artifact,
                version=entry.coord.version,
                scope=None,
                artifacts=(
                    MavenDependencyModuleArtifact(
                        uri=build_root.pathlib_path.joinpath(
                            f".pants.d/bsp/jvm/resolves/{resolve.name}/lib/{entry.file_name}"
                        ).as_uri()
                    ),
                ),
            ),
        )
        for entry in applicable_lockfile_entries
    ]

    return BSPDependencyModulesResult(
        modules=tuple(modules),
        digest=resolve_digest,
    )

def update_venue(
    venue: Venue,
    contact_data: venues_serialize.VenueContactModel = None,
    **attrs: typing.Any,
) -> Venue:
    validation.validate_coordinates(attrs.get("latitude"), attrs.get("longitude"))
    modifications = {field: value for field, value in attrs.items() if venue.field_exists_and_has_changed(field, value)}

    validation.check_venue_edition(modifications, venue)

    if contact_data:
        upsert_venue_contact(venue, contact_data)

    if not modifications:
        return venue

    business_unit_id = modifications.get("businessUnitId")
    if business_unit_id and venue.businessUnit:
        if venue.businessUnitId != business_unit_id and venue.isBusinessUnitMainVenue:
            delete_business_unit(venue.businessUnit)
            logger.info(
                "Change Venue.businessUnitId where Venue.siret and BusinessUnit.siret are equal",
                extra={"venue_id": venue.id, "business_unit_id": business_unit_id},
            )

    venue.populate_from_dict(modifications)

    repository.save(venue)
    search.async_index_venue_ids([venue.id])

    indexing_modifications_fields = set(modifications.keys()) & set(VENUE_ALGOLIA_INDEXED_FIELDS)
    if indexing_modifications_fields or contact_data:
        search.async_index_offers_of_venue_ids([venue.id])

    return venue

def getBugzillaClassForURL(url):
    log.debug("Choosing subclass for %s" % url)
    s = xmlrpclib.ServerProxy(url)
    rhbz = False
    bzversion = ''
    c = None

    # Check for a RH-only method
    try:
        log.debug("Checking for RH Bugzilla method bugzilla.getProdInfo()")
        prodinfo = s.bugzilla.getProdInfo()
        rhbz = True
    except xmlrpclib.Fault:
        pass
    log.debug("rhbz=%s" % str(rhbz))

    # Try to get the bugzilla version string
    try:
        log.debug("Checking return value of Buzilla.version()")
        r = s.Bugzilla.version()
        bzversion = r['version']
    except xmlrpclib.Fault:
        pass
    log.debug("bzversion='%s'" % str(bzversion))

    if rhbz:
        if bzversion.startswith('3.'):
            c = RHBugzilla3
        elif bzversion.startswith('4.'):
            c = RHBugzilla4
        else:
            log.debug("No explicit match for RH version %s, us latest we "
                      "know", bzversion)
            c = RHBugzilla4
    else:
        if bzversion.startswith("4."):
            c = Bugzilla4
        elif bzversion.startswith('3.6'):
            c = Bugzilla36
        elif bzversion.startswith('3.4'):
            c = Bugzilla34
        elif bzversion.startswith('3.2'):
            c = Bugzilla32
        else:
            log.debug("No explicit match for %s, fall through", bzversion)
            c = Bugzilla3

    return c

async def validate_python_dependencies(
    request: PythonValidateDependenciesRequest,
    python_setup: PythonSetup,
) -> ValidatedDependencies:
    dependencies = await MultiGet(Get(WrappedTarget, Address, d) for d in request.dependencies)

    # Validate that the ICs for dependencies are all compatible with our own.
    target_ics = request.field_set.interpreter_constraints.value_or_global_default(python_setup)
    non_subset_items = []
    for dep in dependencies:
        if not dep.target.has_field(InterpreterConstraintsField):
            continue
        dep_ics = dep.target[InterpreterConstraintsField].value_or_global_default(python_setup)
        if not interpreter_constraints_contains(
            dep_ics, target_ics, python_setup.interpreter_universe
        ):
            non_subset_items.append(f"{dep_ics}: {dep.target.address}")

    if non_subset_items:
        raise Exception(
            f"The target {request.field_set.address} has the `interpreter_constraints` {target_ics},\n            which are not a subset of the `interpreter_constraints` of some of its dependencies:\n            {bullet_list(sorted(non_subset_items))}\n            To fix this, you should likely adjust {request.field_set.address}'s\n            `interpreter_constraints` to match the narrowest range in the above list."
        )

    return ValidatedDependencies()

def update_state(self, raw_state):
    self.state = json.loads(raw_state)
    self.scope.clear()
    for o in self.state.get("room").get("contains"):
        self.scope.append(o.get("shortname"))
    for o in self.state.get("inventory"):
        self.scope.append(o.get("shortname"))
    self.here_text.contents.clear()
    self.user_text.contents.clear()
    self.minimap_grid.contents.clear()

    self.here_text.contents.extend(list(
        zip(self.here_info(),
            [self.here_text.options()]*3
            )
        ))

    self.user_text.contents.extend(list(
        zip(self.user_info(),
            [self.user_text.options()]*2
            )
        ))

    self.minimap_grid.contents.extend(list(
        zip(self.generate_minimap(),
            [self.minimap_grid.options()]*3
            )
        ))

def unicode_replace__Unicode_Unicode_Unicode_ANY(space, w_self, w_old,
                                                 w_new, w_maxsplit):
    if len(w_old._value):
        parts = _split_with(w_self._value, w_old._value,
                            space.int_w(w_maxsplit))
    else:
        self = w_self._value
        maxsplit = space.int_w(w_maxsplit)
        parts = _split_into_chars(self, maxsplit)

    try:
        return W_UnicodeObject(w_new._value.join(parts))
    except MemoryError:
        raise OperationError(
            space.w_OverflowError,
            space.wrap("replace string is too long"))

