def upload_translation(request, project, subproject, lang):
    obj = get_object_or_404(Translation, language__code=lang, subproject__slug=subproject, subproject__project__slug=project)

    if request.method == 'POST':
        form = UploadForm(request.POST, request.FILES)
        if form.is_valid():
            translation_file = form.cleaned_data['file']
            # Process the uploaded file and merge content into the translation
            with open(translation_file.path, 'r') as file:
                content = file.read()
                obj.content = content  # Assuming 'content' is a field in Translation model
                obj.save()
            messages.add_message(request, messages.INFO, _('File content successfully merged into translation.'))

    return HttpResponseRedirect(obj.get_absolute_url())

def upload_translation(request, project, subproject, lang):
    obj = get_object_or_404(Translation, language__code=lang, subproject__slug=subproject, subproject__project__slug=project)

    if request.method == 'POST':
        form = UploadForm(request.POST, request.FILES)
        if form.is_valid():
            translation_file = form.cleaned_data['file']
            # Process the uploaded file content
            with open(translation_file.path, 'r') as file:
                content = file.read()
                # Assuming we have a method to merge content into the translation
                obj.merge_content(content)
            messages.add_message(request, messages.INFO, _('File content successfully merged into translation.'))

    return HttpResponseRedirect(obj.get_absolute_url())

def path2url(path):
    """
    returns path
    """
    if sys.platform.startswith('java'):
        href = os.path.abspath(path)
        href = href.replace('\', '/')
        return 'file:' + href
    else:
        return u'file:' + urllib.pathname2url(os.path.abspath(path))

