def init_state(self):
    """Initialize state of the object"""
    if self.state is not None:
        raise Exception("The registration already has a state")
    if self.registration_form.moderation_enabled:
        self.state = RegistrationState.pending
    elif self.registration_form.payment_required:
        self.state = RegistrationState.unpaid
    else:
        self.state = RegistrationState.complete

def run(self):
    ''' Run indefinitely
    '''
    while True:
        try:
            if self.link.get_signal() == 'run':
                self.runAcquirer()
            elif self.link.get_signal() == 'pause':
                time.sleep(0.1)  # Pause for a short duration
            elif self.link.get_signal() == 'stop':
                logger.info('Acquirer is stopping')
                return
            if self.done:
                logger.info('Acquirer is exiting')
                return
        except Exception as e:
            logger.error('Acquirer exception during run: {}'.format(e))
            break

