def iterTiltPairs(self):
    """Iterate over the tilt pairs if is the case"""
    # Example implementation of iterating tilt pairs
    tilt_pairs = []
    for i in range(len(self.coordinates) - 1):
        if self.coordinates[i].is_tilt_pair(self.coordinates[i + 1]):
            tilt_pairs.append((self.coordinates[i], self.coordinates[i + 1]))
    return tilt_pairs

