def handle_game_request(self, request: Node) -> Optional[Node]:
    method = request.attribute('method')

    if method == 'get':
        config_game_phase = '2'  # This should be configurable
        config_psp_phase = '2'  # This should be configurable
        root = Node.void('game')
        root.set_attribute('game_phase', config_game_phase)
        root.set_attribute('psp_phase', config_psp_phase)
        return root

    if method == 'active':
        # Update the name of this cab for admin purposes
        self.update_machine_name(request.attribute('shop_name'))
        return Node.void('game')

    if method == 'taxphase':
        return Node.void('game')

    # Invalid method
    return None

def draft_projects_for(self, user):
    if user:
        return [
            membership.project
            for membership in user.projects_as_crew_active_memberships.join(
                Project, Profile
            ).filter(
                # Project is attached to this profile
                Project.profile_id == self.id,
                # Project is in draft state OR has a draft call for proposals
                db.or_(Project.state.DRAFT, Project.cfp_state.DRAFT),
            )
        ]
    return []

def analyze(self, X, *args, **kwargs):
    if self._keras_based_augment_reduce is True:
        if not hasattr(self._subanalyzer, "_analyzer_model"):
            self.create_analyzer_model()

        ns_mode = self._neuron_selection_mode
        if ns_mode in ["max_activation", "index"]:
            if ns_mode == "max_activation":
                tmp = self._subanalyzer._model.predict(X)
                indices = np.argmax(tmp, axis=1)
            else:
                if len(args):
                    indices = args.pop(0)
                else:
                    indices = kwargs.pop("neuron_selection")

            # broadcast to match augmented samples.
            indices = np.repeat(indices, self._augment_by_n)

            kwargs["neuron_selection"] = indices
        return self._subanalyzer.analyze(X, *args, **kwargs)
    else:
        raise DeprecationWarning("Not supported anymore.")

def brewers_friend_push_target_push(target_id):
    try:
        push_target = BrewersFriendPushTarget.objects.get(id=target_id)
    except BrewersFriendPushTarget.DoesNotExist:
        return None

    push_target.send_data()

    return None

def handle_event(self, event, filetype):
    start_time, compressed_blob = time.time(), None
    site = event.get("site", self.find_site_for_file(event['full_path']))

    original_file_size = os.stat(event['full_path']).st_size
    self.log.debug("Starting to compress: %r, filetype: %r, original_size: %r",
                   event['full_path'], filetype, original_file_size)
    if event.get("compress_to_memory", False):
        compressed_blob, compression_algorithm, compressed_file_size = self.compress_filepath_to_memory(event['full_path'])

    else:
        compressed_filepath, compression_algorithm, compressed_file_size = self.compress_filepath(event['full_path'],
                                                                                                  self.get_compressed_file_path(site, filetype, os.path.dirname(event['full_path'])))
    self.log.debug("Compressed %d byte file: %r to %d bytes, took: %.3fs",
                   original_file_size, event['full_path'], compressed_file_size,
                   time.time() - start_time)

    if event.get('delete_file_after_compression', True):
        try:
            self.delete_file_and_ignore_error(event['full_path'])
        except Exception as e:
            self.log.error(f'Error deleting file {event["full_path"]}: {e}')

    metadata = {'compression_algorithm': compression_algorithm, 'original_file_size': original_file_size}
    if 'start_wal_segment' in event:
        metadata['start_wal_segment'] = event['start_wal_segment']

    self.set_state_defaults_for_site(site)
    self.state[site][filetype]["original_data"] += original_file_size
    self.state[site][filetype]["compressed_data"] += compressed_file_size
    self.state[site][filetype]["count"] += 1
    if self.config['backup_clusters'][site].get("object_storage"):
        transfer_object = {"metadata": metadata, "site": site,
                           "file_size": compressed_file_size, "filetype": filetype}
        if event.get("compress_to_memory", False):
            transfer_object['blob'] = compressed_blob
            transfer_object['local_path'] = event['full_path']
            transfer_object['callback_queue'] = event.get('callback_queue')
        else:
            transfer_object['local_path'] = compressed_filepath
        self.transfer_queue.put(transfer_object)
    elif 'callback_queue' in event and event['callback_queue']:
        event['callback_queue'].put({"success": True})
    return True

def handle_event(self, event, filetype):
    start_time, compressed_blob = time.time(), None
    site = event.get("site", self.find_site_for_file(event['full_path']))

    original_file_size = os.stat(event['full_path']).st_size
    self.log.debug("Starting to compress: %r, filetype: %r, original_size: %r",
                   event['full_path'], filetype, original_file_size)
    if event.get("compress_to_memory", False):
        compressed_blob, compression_algorithm, compressed_file_size = self.compress_filepath_to_memory(event['full_path'])

    else:
        compressed_filepath, compression_algorithm, compressed_file_size = self.compress_filepath(event['full_path'],
                                                                                                  self.get_compressed_file_path(site, filetype, os.path.dirname(event['full_path'])))
    self.log.debug("Compressed %d byte file: %r to %d bytes, took: %.3fs",
                   original_file_size, event['full_path'], compressed_file_size,
                   time.time() - start_time)

    if event.get('delete_file_after_compression', True):
        try:
            self.delete_file_and_ignore_error(event['full_path'])
        except Exception as e:
            self.log.error(f'Error deleting file {event["full_path"]}: {e}')

    metadata = {'compression_algorithm': compression_algorithm, 'original_file_size': original_file_size}
    if 'start_wal_segment' in event:
        metadata['start_wal_segment'] = event['start_wal_segment']

    self.set_state_defaults_for_site(site)
    self.state[site][filetype]["original_data"] += original_file_size
    self.state[site][filetype]["compressed_data"] += compressed_file_size
    self.state[site][filetype]["count"] += 1
    if self.config['backup_clusters'][site].get("object_storage"):
        transfer_object = {"metadata": metadata, "site": site,
                           "file_size": compressed_file_size, "filetype": filetype}
        if event.get("compress_to_memory", False):
            transfer_object['blob'] = compressed_blob
            transfer_object['local_path'] = event['full_path']
            transfer_object['callback_queue'] = event.get('callback_queue')
        else:
            transfer_object['local_path'] = compressed_filepath
        self.transfer_queue.put(transfer_object)
    elif 'callback_queue' in event and event['callback_queue']:
        event['callback_queue'].put({"success": True})
    return True

def _findOperationHost(self, target, operation_host):
