def handle_game_request(self, request: Node) -> Optional[Node]:
    method = request.attribute('method')

    if method == 'get':
        config_game_phase = '2'  # This should be configurable
        config_psp_phase = '2'  # This should be configurable
        root = Node.void('game')
        root.set_attribute('game_phase', config_game_phase)
        root.set_attribute('psp_phase', config_psp_phase)
        return root

    if method == 'active':
        # Update the name of this cab for admin purposes
        self.update_machine_name(request.attribute('shop_name'))
        return Node.void('game')

    if method == 'taxphase':
        return Node.void('game')

    # Invalid method
    return None

def draft_projects_for(self, user):
    if user:
        return [
            membership.project
            for membership in user.projects_as_crew_active_memberships.join(
                Project, Profile
            ).filter(
                # Project is attached to this profile
                Project.profile_id == self.id,
                # Project is in draft state OR has a draft call for proposals
                db.or_(Project.state.DRAFT, Project.cfp_state.DRAFT),
            )
        ]
    return []

def analyze(self, X, *args, **kwargs):
    if self._keras_based_augment_reduce is True:
        if not hasattr(self._subanalyzer, "_analyzer_model"):
            self.create_analyzer_model()

        ns_mode = self._neuron_selection_mode
        if ns_mode in ["max_activation", "index"]:
            if ns_mode == "max_activation":
                tmp = self._subanalyzer._model.predict(X)
                indices = np.argmax(tmp, axis=1)
            else:
                if len(args):
                    indices = args.pop(0)
                else:
                    indices = kwargs.pop("neuron_selection")

            # broadcast to match augmented samples.
            indices = np.repeat(indices, self._augment_by_n)

            kwargs["neuron_selection"] = indices
        return self._subanalyzer.analyze(X, *args, **kwargs)
    else:
        raise DeprecationWarning("Not supported anymore.")

