def parse_shader(sres, c, con, defs, lines, parse_attributes):
    skip_till_endif = 0
    skip_else = False
    vertex_structure_parsed = False
    vertex_structure_parsing = False

    stack = []

    if parse_attributes == False:
        vertex_structure_parsed = True

    for line in lines:
        line = line.lstrip()

        # Preprocessor
        if line.startswith('#ifdef') or line.startswith('#ifndef'):
            s = line.split(' ')[1]
            found = find_def(defs, s)
            if line.startswith('#ifndef'):
                found = not found
            if found == False:
                stack.append(0)
            else:
                stack.append(1)
            continue

        if line.startswith('#else'):
            stack[-1] = 1 - stack[-1]
            continue

        if line.startswith('#endif'):
            stack.pop()
            continue

        if len(stack) > 0 and stack[-1] == 0:
            continue

        if vertex_structure_parsed == False and line.startswith('in '):
            vertex_structure_parsing = True
            vd = {}
            s = line.split(' ')
            vd['size'] = int(s[1][-1:])
            vd['name'] = s[2][:-1]
            sres['vertex_structure'].append(vd)
        if vertex_structure_parsing == True and len(line) > 0 and line.startswith('//') == False and line.startswith('in ') == False:
            vertex_structure_parsed = True

        if line.startswith('uniform ') or line.startswith('//!uniform'):  # Uniforms included from header files
            s = line.split(' ')
            # uniform sampler2D myname;
            # uniform layout(RGBA8) image3D myname;
            if s[1].startswith('layout'):
                ctype = s[2]
                cid = s[3][:-1]
            else:
                ctype = s[1]
                cid = s[2][:-1]

            found = False  # Unique check
            if ctype == 'sampler2D' or ctype == 'sampler2DShadow' or ctype == 'sampler3D' or ctype == 'image2D' or ctype == 'image3D':  # Texture unit
                for tu in con['texture_units']:  # Texture already present
                    if tu['name'] == cid:
                        found = True
                        break
                if found == False:
                    tu = {}
                    tu['name'] = cid
                    # sampler2D / image2D
                    if ctype == 'image2D' or ctype == 'image3D':
                        tu['is_image'] = True
                    # Check for link
                    for l in c['links']:
                        if l['name'] == cid:
                            valid_link = True

                            if 'ifdef' in l:
                                def_found = False
                                for d in defs:
                                    for link_def in l['ifdef']:
                                        if d == link_def:
                                            def_found = True
                                            break
                                    if def_found:
                                        break
                                if not def_found:
                                    valid_link = False

                            if 'ifndef' in l:
                                def_found = False
                                for d in defs:
                                    for link_def in l['ifndef']:
                                        if d == link_def:
                                            def_found = True
                                            break
                                    if def_found:
                                        break
                                if def_found:
                                    valid_link = False

                            if valid_link:
                                tu['link'] = l['link']
                            break
                    con['texture_units'].append(tu)
            else:  # Constant
                if cid.find('[') != -1:  # Float arrays
                    cid = cid.split('[')[0]
                    ctype = 'floats'
                for const in con['constants']:
                    if const['name'] == cid:
                        found = True
                        break
                if found == False:
                    const = {}
                    const['type'] = ctype
                    const['name'] = cid
                    # Check for link
                    for l in c['links']:
                        if l['name'] == cid:
                            valid_link = True

                            if 'ifdef' in l:
                                def_found = False
                                for d in defs:
                                    for link_def in l['ifdef']:
                                        if d == link_def:
                                            def_found = True
                                            break
                                    if def_found:
                                        break
                                if not def_found:
                                    valid_link = False

                            if 'ifndef' in l:
                                def_found = False
                                for d in defs:
                                    for link_def in l['ifndef']:
                                        if d == link_def:
                                            def_found = True
                                            break
                                    if def_found:
                                        break
                                if def_found:
                                    valid_link = False

                            if valid_link:
                                const['link'] = l['link']
                            break
                    con['constants'].append(const)

def get_current_user():
    if settings.UNIT_TEST_MODE:
        user_via_env = None
        if os.environ['USER_EMAIL'] != '':
            user_via_env = User(email=os.environ['USER_EMAIL'])
        return user_via_env

    jwt = session.get('id_token')
    if jwt:
        try:
            idinfo = id_token.verify_oauth2_token(
                jwt, requests.Request(), settings.GOOGLE_SIGN_IN_CLIENT_ID)
            user_via_jwt = User(email=idinfo['email'])
            return user_via_jwt

        except ValueError:
            session.clear()
            pass

    user_info, signature = session.get('signed_user_info', (None, None))
    if user_info:
        try:
            xsrf.validate_token(
                signature,
                str(user_info),
                timeout=xsrf.REFRESH_TOKEN_TIMEOUT_SEC)
            user_via_signed_user_info = User(email=user_info['email'])
            return user_via_signed_user_info

        except xsrf.TokenIncorrect:
            session.clear()
            pass

    return None  # User is not signed in.

def get_kube_client(in_cluster=conf.getboolean('kubernetes', 'in_cluster'), kubeconfig_path=None):
    if kubeconfig_path:
        return _load_kube_config(False, kubeconfig_path)
    return _load_kube_config(in_cluster)


def _load_kube_config(in_cluster, kubeconfig_path=None):
    from kubernetes import config, client
    if in_cluster:
        config.load_incluster_config()
        return client.CoreV1Api()
    else:
        if kubeconfig_path:
            config.load_kube_config(config_file=kubeconfig_path)
        else:
            config.load_kube_config()
        return client.CoreV1Api()

def _expand_as():
    def _impl(inputs, input_types):
        return inputs[0]

    return _impl

def __init__(self, opt, shared=None):
    # Check for setup_data
    self.opt = copy.deepcopy(opt)
    print("[DialogTeacher initializing.]")
    if not hasattr(self, 'setup_data'):
        raise RuntimeError('Must implement setup_data or subclass a class' +
                           ' which implements it (e.g. FbDialogTeacher)' +
                           ' in order to use this class.')

    self.datatype = opt['datatype']
    self.startTime = time.time()
    if not hasattr(self, 'id'):
        self.id = opt.get('task', 'teacher')

    # first initialize any shared objects
    if shared and shared.get('data'):
        self.data = shared['data']
    else:
        if opt.get('numthreads', 1) == 1:
            self.data = TextData(self.setup_data(opt['datafile']),
                                 cands=self.label_candidates(),
                                 random=self.datatype == 'train')
        else:
            self.data = HogwildTextData(self.setup_data(opt['datafile']),
                                        cands=self.label_candidates(),
                                        random=self.datatype == 'train')

    if shared and shared.get('metrics'):
        self.metrics = shared['metrics']
    else:
        self.metrics = Metrics(opt)
    self.reset()

def _detect_local_metal():
    dev = tvm.metal()
    if not dev.exist:
        return None
    return tvm.target.Target(
        {
            "kind": "metal",
            "max_shared_memory_per_block": 32768,
            "max_threads_per_block": dev.max_threads_per_block,
            "thread_warp_size": 32,
        },
        host=tvm.target.Target(
            {
                "kind": "llvm",
                "mtriple": "arm64-apple-macos",
                "mcpu": "apple-latest",
            }
        ),
    )

def browser(request, percy, live_server):
    window_size = request.config.getoption('window_size')
    window_width, window_height = list(map(int, window_size.split('x', 1)))

    driver_type = request.config.getoption('selenium_driver')
    if driver_type == 'chrome':
        options = webdriver.ChromeOptions()
        options.add_argument('headless')
        options.add_argument('disable-gpu')
        options.add_argument('window-size={}'.format(window_size))
        chrome_path = request.config.getoption('chrome_path')
        if chrome_path:
            options.binary_location = chrome_path
        chromedriver_path = request.config.getoption('chromedriver_path')
        if chromedriver_path:
            driver = webdriver.Chrome(
                executable_path=chromedriver_path,
                chrome_options=options,
            )
        else:
            driver = webdriver.Chrome(
                chrome_options=options,
            )
    elif driver_type == 'firefox':
        driver = webdriver.Firefox()
    elif driver_type == 'phantomjs':
        phantomjs_path = request.config.getoption('phantomjs_path')
        if not phantomjs_path:
            phantomjs_path = os.path.join(
                'node_modules',
                'phantomjs-prebuilt',
                'bin',
                'phantomjs',
            )
        driver = webdriver.PhantomJS(executable_path=phantomjs_path)
    else:
        raise pytest.UsageError('--driver must be specified')

    driver.set_window_size(window_width, window_height)

    def fin():
        # Teardown Selenium.
        try:
            driver.close()
        except Exception:
            pass
        driver.quit()

    request.node._driver = driver
    request.addfinalizer(fin)

    browser = Browser(driver, live_server, percy)

    if hasattr(request, 'cls'):
        request.cls.browser = browser
    request.node.browser = browser

    # bind webdriver to percy for snapshots
    percy.loader.webdriver = driver

    return driver

def validate(self, exclusion):
    geo_group = exclusion.modified_measure.geographical_area
    excluded = exclusion.excluded_geographical_area

    if not geo_group.members.filter(
        member__sid=excluded.sid,
        valid_between__contains=exclusion.modified_measure.effective_valid_between,
    ).exists():
        raise self.violation(exclusion)

