def _addExtraCfg(self, cmd, devices=tuple(), use_lvmpolld=True):
    newcmd = [constants.EXT_LVM, cmd[0]]

    if devices:
        dev_filter = _buildFilter(devices)
    else:
        dev_filter = self._getCachedFilter()

    conf = _buildConfig(
        dev_filter=dev_filter,
        use_lvmpolld="1" if use_lvmpolld else "0")
    newcmd += ["--config", conf]

    if len(cmd) > 1:
        newcmd += cmd[1:]

    return newcmd

def _update_migration_status(
    self, migration_key: MigrationKey, status: Status
) -> None:
    statement = f"INSERT INTO {TABLE_NAME} FORMAT JSONEachRow"
    data = [
        {
            "group": migration_key.group.value,
            "migration_id": migration_key.migration_id,
            "timestamp": datetime.now(),
            "status": status.value,
            "version": 2,
        }
    ]
    self.__connection.execute(
        statement, data, settings={"load_balancing": "in_order"}
    )

